const LOTES=[{"codigo":"ebserh-enfermeiro-gp4","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/grupo-4-enfermageme3cnsgp04-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/ebserrhassistencial2024_gabarito_definitivo.pdf","cargo":"Enfermagem Grupo 4","orgao":"EBSERH","ano":2025,"questoes":[{"numero":11,"disciplina":"Legislação da EBSERH","assunto":"Lei 12.550/2011","enunciado":"A Empresa Brasileira de Serviços Hospitalares (Ebserh) é uma empresa pública vinculada ao Ministério da Educação, criada pela Lei Federal nº 12.550/2011. A respeito de suas finalidades, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Oferecer suporte ao Sistema Único de Saúde (SUS): a empresa contribui para o atendimento da população por meio dos hospitais universitários. ( ) Administrar hospitais universitários federais: a Ebserh gerencia e aprimora a infraestrutura e os serviços dos hospitais vinculados às universidades federais que estabeleceram contrato com ela. ( ) Apoiar o ensino e a pesquisa: a empresa valoriza e ampara o ensino-aprendizagem e a formação de pessoas no campo da saúde pública em instituições federais de ensino superior e em instituições congêneres. As afirmativas são, respectivamente,","alternativas":["V – F – V.","F – V – V.","V – V – F.","V – F – F.","V – V – V"],"correta":"E"},{"numero":12,"disciplina":"Legislação da EBSERH","assunto":"Regimento Interno","enunciado":"Segundo o Regimento Interno da Ebserh, a estrutura organizacional da empresa conta com Colegiados Internos, que têm a função de atender a necessidades que não possam ser resolvidas isoladamente pelas áreas organizacionais. Os Colegiados Internos são classificados em função de sua duração e atribuição, como nos exemplos a seguir. I. É de duração perene, atua de forma consultiva no nível tático, composto por profissionais de referência na área de atuação, analisando detalhadamente temas específicos e de grande amplitude, como padronizações técnicas e definiçõ es de melhores práticas. II. É de duração temporária, atua de forma consultiva ou executiva no nível técnico operacional, na execução de ações ou projetos específicos, com prazo preestabelecido, propondo soluções para problemas determinados ou executando a ções transversais que envolvam mais de uma área organizacional. Os trechos I e II se referem, respectivamente, aos Colegiados Internos organizados sob a forma de","alternativas":["Comissão e Escritório.","Comitê e Centro de Competência.","Centro de Competência e Comissão.","Câmara Técnica e Grupo de Trabalho.","Núcleo Técnico Operacional e Comitê."],"correta":"D"},{"numero":13,"disciplina":"Legislação da EBSERH","assunto":"Lei 12.550/2011","enunciado":"A Lei nº 12.550/2011 e o Regulamento de Pessoal da Empresa Brasileira de Serviços Hospitalares ( Ebserh) disponibilizam normativas a respeito dos integrantes do quadro de pessoal da Empresa. Considerando as normas citadas, é correto afirmar que a Ebserh está autorizada a","alternativas":["admitir profissional qualificado para realização de serviços técnicos especializados, por meio de indicação.","recrutar terceirizados para funções gratificadas em unidades hospitalares, mediante processo seletivo simplificado.","selecionar pessoal técnico e administrativo por tempo indeterminado, mediante concurso público.","contratar empregados temporários, observado o prazo máximo de seis anos, mediante prestação de serviços.","obter servidores titulares de cargo efetivo em exercício em instituição federal de ensino que possui contrato com a Empresa, mediante solicitação de cessão"],"correta":"C"},{"numero":14,"disciplina":"Legislação da EBSERH","assunto":"Estatuto Social","enunciado":"A partir da sua criação, a Ebserh passou a ser a responsável pela gestão de hospitais universitários federais, finalidade planejada e implementada mediante o Conselho de Administração, um dos seus principais órgãos administrativos. Segundo o Estatuto Social da Ebserh, o Conselho de Administração é um órgão colegiado composto por nove membros. A respeito desses membros, assinale a afirmativa correta.","alternativas":["Um membro é o Presidente da Empresa, que ocupa a presidência executiva do conselho.","Um membro é indicado pelo Ministro da Gestão e da Inovação em Serviços Público, sendo obrigatoriamente diretor de hospital universitário federal.","Três membros são indicados pelo Ministro da Educação, dos quais um será o Presi dente do Conselho e outro, o substituto em suas ausências e seus impedimentos.","Um membro é reitor de universidade federal, eleito para o cargo pela Associação Nacional dos Docentes das Instituições Federais de Ensino Superior.","Dois membros são repr esentantes dos empregados, eleitos para participar das deliberações sobre assuntos que envolvam relações sindicais, remuneração e questões de previdência"],"correta":"C"},{"numero":15,"disciplina":"Legislação da EBSERH","assunto":"Ética Institucional","enunciado":"A Comissão de Ética da Ebserh (CEE) está encarregada de orientar e aconselhar sob re as questões éticas dos colaboradores da instituição, no tratamento com as pessoas e com o patrimônio público. A CEE é um órgão autônomo, de caráter","alternativas":["deliberativo, cabendo-lhe deliberar sobre condutas antiéticas e sobre as transgressões das normas da Ebserh levadas ao seu conhecimento.","consultivo, sendo de sua alçada o controle social e o apoio à Diretoria Executiva e ao Conselho de Administração na aplicação de eventuais medidas disciplinares.","fiscalizador, cabendo-lhe inspecionar o cumprimento do limite de participação da empresa no custeio dos benefícios de assistência à saúde e de previdência complementar.","orientador, pertencendo -lhe assessorar o Conselho de Administração nos processos de indicação, avaliação e remuneração dos administra dores, conselheiros fiscais e demais membros de órgãos estatutários.","assessorial, sendo de sua responsabilidade monitorar exposições de risco da Ebserh, podendo requerer, entre outras, informações detalhadas sobre políticas e procedimentos considerados impróprios. Políticas Públicas de Saúde e Educação"],"correta":"A"},{"numero":16,"disciplina":"Legislação do SUS","assunto":"Controle Social no SUS","enunciado":"O controle social democrático das políticas de saúde no Brasil se dá, sobretudo, no âmbito dos Conselhos de Saúde e das Conferências de Saúde. Assinale a opção correta no que diz respeito às características e atribuições desses espaços.","alternativas":["Os Conselhos de Saúde são organizados de maneira centralizada, respondendo diretamente às determinações do governo via Conselho Nacional de Saúde.","As Conferências de Saúde ocorrem com regularidade anual no nível nacional, abordando temas determinados em cada evento do ano anterior.","Os Conselhos de Saúde são órgãos colegiados e permanentes, responsáveis diretamente pela execução dos serviços de saúde no território nacional.","As Conferências de Saúde municipais e estaduais ocorrem como etapas prévias da Conferência Nacional, aprovando propostas a serem discutidas nesta.","Os Conselhos de Saúde estão distribuídos nos níveis federal, estadual e municipal, funcionando de maneira subordinada ao executivo de cada unidade administrativa."],"correta":"D"},{"numero":17,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"Com relação à construção histórica do Sistema Único de Saúde (SUS), avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O SUS foi cr iado inicialmente durante o Governo Vargas, voltado, a princípio, apenas para o atendimento aos trabalhadores da economia formal e suas famílias. ( ) A Constituição Federal de 1988 introduziu o fundamento da universalização do SUS e estabeleceu a integração dos serviços públicos de saúde em uma rede regionalizada e hierarquizada. ( ) O projeto inicial do sistema previa a sua evolução para o Sistema Unificado e Descentralizado de Saúde (SUDS), cuja execução permanece em aberto e em progresso. As afirmativas são, respectivamente,","alternativas":["F – V – F.","F – V – V.","V – F – F.","V – V – F.","F – F – V"],"correta":"A"},{"numero":18,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"Leia o trecho a seguir a respeito da insurgência ocorrida no início do século XX durante a campanha de vacinação contra a varíola. A Re volta da Vacina permanece como exemplo quase único na história do país de movimento popular de êxito baseado na defesa do direito dos cidadãos de não serem arbitrariamente tratados pelo governo. Mesmo que a vitória não tenha sido traduzida em mudanças políticas imediatas além da interrupção da vacinação, ela certamente deixou entre os que dela participaram um sentimento profundo de orgulho e de autoestima, passo importante na formação da cidadania. CARVALHO, José Murilo de. Os bestializados. São Paulo: Companhia das Letras, 2019. Segundo o autor, essa situação é exemplar da tensão entre","alternativas":["ciência médica e ignorância popular diante das políticas de saúde.","práticas higienistas e liberdade individual na saúde pública.","passividade das camada s populares e medidas coercitivas do governo.","campanhas educativas e desinformação entre a população.","resistência das elites à vacinação e rápida adesão das classes populares"],"correta":"B"},{"numero":19,"disciplina":"Saúde Coletiva I","assunto":"Determinação Social da Saúde","enunciado":"Sobre os determinantes sociais da saúde, analise o texto seguir. Podemos afirmar que na efetivação e desenvolvimento de si os indivíduos organizam e transformam grupos humanos nos mais diversos níveis e, de um modo ou de outro, a própria humanidade. Dessa forma, para os próprios indivíduos, que são concentr ações vivas e pontos de interação da rede social, a transformação da sociedade resulta em novas condições de ser, novas condições de sua existência, inclusive psicofisiológica; portanto, de sua saúde. BRONZO, Carla; FLEURY-TEIXEIRA, Paulo. “Determinação social da saúde pública”. In: Determinação Social da Saúde e Reforma Sanitária. Rio de Janeiro: Cebes, 2010. Assinale a opção que identifica corretamente a ideia central do texto.","alternativas":["A melhoria na saúde do indivíduo ocorre como tradução fisiológica de mudanças de postura psicológica.","O indivíduo é subordinado às características de sua realidade social, o que inclui seus modos de vida e sua saúde.","A ciência médica substitui as mudanças sociais como principal fator para o aumento da qualidade de vida da população.","O funcionamento do organismo humano molda as regras de convivência, determinando os comportamentos coletivos.","A saúde faz parte dos efeitos do engajamento humano, o qual gera transformações históricas no âmbito da vida social"],"correta":"E"},{"numero":20,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A respeito da possibilidade do uso da arquitetura informacional da blockchain para a gestão em saúde, leia o trecho a seguir. Um estudo da Escola Politécnica da USP propôs uma arquitetura para rastrear medicamentos hospitalares utilizando block chain. Com a ferramenta, apenas transações validadas por uma rede descentralizada seriam registradas, garantindo maior dinamismo e segurança ao processo. No mecanismo de consenso, as entidades que fariam a validação teriam acesso às informações quando uma mercadoria fosse enviada de um lugar a outro. Uma validação centralizada também tem condições de realizar essa tarefa, porém é passível de influência humana, ou seja, uma informação já realizada pode ser alterada. CONTERNO, Ivan. Tecnologia blockchain pode reduzir risco de roubos e fraudes na área da saúde. Jornal da USP, 29/05/2023. In: https://jornal.usp.br. Adaptado. Com base no trecho, é correto afirmar que a principal vantagem de utilizar o sistema blockchain para a gestão em saúde consiste","alternativas":["na criação de um sistema mais eficiente, no qual um órgão unificado pode validar e modificar informações conforme necessário.","na eliminação da influência humana no processo de validação, garantindo que todas as tran sações sejam verificadas autonomamente.","na descentralização do registro de transações, que reduz o risco de alterações indevidas e aumenta a integridade das informações.","na capacidade de modificar registros antigos para corrigir eventuais erros, to rnando a rastreabilidade mais flexível e adaptável às necessidades regulatórias.","na substituição dos mecanismos tradicionais de rastreabilidade, eliminando a necessidade de auditoria por órgãos reguladores."],"correta":"C"},{"numero":21,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"A política regulatória do s planos privados explicita de maneira legal e institucional o fato de que os princípios do SUS de universalidade e igualdade eram formais. O modelo regulatório, da forma como foi adotado, é suplementar e não uma articulação. Sua implantação, de qualquer f orma, foi separada: o modelo regula esse mercado, enquanto o SUS é outra história, com outra regulação e mecanismos decisórios totalmente díspares. São modelos e concepções diferentes: um é direito do consumidor e defende o mercado; o outro é direito de ci dadania, obrigação do Estado. MENICUCCI, T. M. G. História da reforma sanitária brasileira e do Sistema Único de Saúde. História, Ciências, Saúde – Manguinhos, Rio de Janeiro, v. 21, n. 1, 2014. A criação de um sistema nacional de saúde envolve uma série d e decisões políticas e organizacionais. Com base no trecho, é correto afirmar que o sistema brasileiro","alternativas":["adota um modelo híbrido, no qual a regulação dos planos de saúde privados se integra aos serviços públicos e forma um sistema único e coordenado em seu funcionamento.","opera com base na universalização plena da saúde, garantindo que o sistema público e os planos privados sejam regulados pelos mesmos mecanismos e princípios.","descaracteriza os princípios da universalidade e da igualdade, tornando o acesso aos serviços de saúde condicionado à contratação de assistência suplementar.","formaliza um sistema único de assistência, no qual os planos de saúde privados são considerados complementares ao serviço público e seguem sua mesma lógica de gestão.","funciona como um sistema segmentado, no qual os planos de saúde privados operam de forma paralela ao serviço público, com regulações e princípios distintos"],"correta":"D"},{"numero":22,"disciplina":"Enfermagem","assunto":"Ética e Legislação em Enfermagem","enunciado":"A respeito dos limites entre ciência ética, leia o relato a seguir. Em 201 8, o cientista chinês He Jiankui causou controvérsia na comunidade científica quando revelou ter editado o código genético de dois embriões saudáveis com o objetivo de torná -los imunes à transmissão do HIV contraído pelos pais. O resultado foi o nascimento de duas meninas gêmeas geneticamente modificadas com a técnica de CRISPR -cas9, uma ferramenta genética que corta a sequência do DNA e o reconfigura para obter a modificação desejada. A repercussão do experimento levou à demissão e à condenação a três anos de prisão na China. Experimento chinês confronta limites entre ética e ciência , 2019, In: https://www.ipea.gov.br/. Adaptado. Considerando os princípios da bioética, assinale a afirmativa que identifica problemas éticos suscitados pelo experimento citado.","alternativas":["O desrespeito às normas comerciais, pois a alteração genética das bebês pode impactar o mercado de vacinas.","A inviabilidade econômica da técnica, que exige um alto investimento sem benefícios significativos.","Os riscos imprevisíveis de alterações genéticas em seres humanos, que vão produzir óvulos e espermatozoides com essa mutação.","A falha metodológica do estudo, que não seguiu protocolos científicos rigorosos para garantir a eficácia.","O comprometimento da viabilidade das futuras gerações, pois as edições genéticas causam instabilidade no DNA"],"correta":"C"},{"numero":23,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Com relação à Atenção Primária à Saúde (APS), avalie as afirmativas a seguir. I. A APS tem o foco na diagnose e no tratamento das enfermidades, dada a dificuldade de ações preventivas na escala de sua atuação. II. A APS otimiza os atendimentos com equipes capazes de abordar as situações menos graves, evitando o encaminhamento a especialistas. III. A APS é o foco principal das iniciativas voltada s para a educação em saúde, dado que é a porta de entrada preferencial no sistema de saúde. Está correto o que se afirma em","alternativas":["I, II e III.","I e II, apenas.","I e III, apenas.","II e III, apenas.","III, apenas"],"correta":"E"},{"numero":24,"disciplina":"Enfermagem","assunto":"Política Nacional de Humanização","enunciado":"A Política Naci onal de Humanização (PNH), ou HumanizaSUS, busca qualificar a saúde pública no Brasil com um foco na organização das dinâmicas de trabalho. A PNH comporta as características indicadas a seguir, à exceção de uma. Assinale-a.","alternativas":["A valorização dos gestores d e saúde como parte essencial da implementação da humanização no SUS.","A autonomia do usuário no cuidado em saúde, garantindo participação ativa no próprio tratamento.","A transferência de responsabilidade para as famílias, atribuindo-lhes papel central na condução dos cuidados.","A articulação entre formação e serviços, promovendo uma educação permanente para profissionais da saúde.","A participação de profissionais e usuários nas ações de saúde junto a gestores, criando espaços de escuta e cogestão"],"correta":"C"},{"numero":25,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"A Estratégia de Saúde da Família (ESF) é uma orientação fundamental do oferecimento de atenção básica à população. Assinale a afirmativa que apresenta corretamente uma característica da ESF.","alternativas":["Prioriza a prevenção de enfermidades entre indivíduos saudáveis, responsáveis pela sustentação material da família.","É operacionalizada por equipes multiprofissionais que atendem um número definido de pessoas em um território.","Executa um serviço ass istencial centralizado em unidades de saúde de grande porte estrategicamente posicionadas.","É orientada ao atendimento de coletividades em vez de indivíduos devido à natureza social de sua atuação.","Opera com equipes itinerantes de assistência social , que diminuem a necessidade de atendimento médico."],"correta":"B"},{"numero":26,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"A Política Nacional de Atenção Hospitalar (PNHOSP) define orientações para reestruturar a assistência hospitalar no SUS, com o objetivo de melhorar a qualidade dos cuidados e a eficiên cia na gestão. As iniciativas listadas a seguir reorganizam e qualificam a atenção hospitalar de acordo com o disposto pela PNHOSP, à exceção de uma. Assinale-a.","alternativas":["A adoção de um sistema experimental de triagem por inteligência artificial para reduzir custos.","A adoção de protocolos clínicos para reduzir a variabilidade no padrão de tratamentos.","A instalação de um sistema de gestão de estoques para evitar desperdício de medicamentos.","A introdução da telemedicina nas unidades afastadas para permitir o acesso remoto a especialistas.","A mobilização de equipes multidisciplinares para fornecer acompanhamento contínuo aos pacientes"],"correta":"A"},{"numero":27,"disciplina":"Legislação do SUS","assunto":"Direitos dos Usuários do SUS","enunciado":"A Resolução CNS nº 553/2017 estabelece os direitos e deveres da pessoa usuária da saúde, a serem observados por paciente e equipe no dia a dia da prestação de serviços. Assinale a opção que indica uma violação de um direito ou de um dever exposto na resolução.","alternativas":["Uma paciente faz uma reclamação formal sobre o atendimento e tem seu pedido encaminhado para análise.","Um paciente idoso chega com mal -estar a uma unidade de saúde sem documentação, mas é prontamente atendido.","Uma paciente consegue agendar um exame para dali a seis meses devido a critérios de prioridade clínica.","Um paciente não emergencial se irrita com o tempo médio de espera e ameaça agressivamente formalizar uma reclamação.","Uma paciente solicita um exame realizado há pouco tempo e tem o pedido negado devido a protocolos de periodicidade"],"correta":"D"},{"numero":28,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"As Redes de Atenção à Saúde (RAS) são estruturas organizacionais projetadas para superar a fragmentação dos serviços de saúde. Sobre o tema, avalie os itens a seguir. I. Os serviços são organizados de maneira hierárquica, com funções definidas e de acordo com a complexidade dos casos. II. As RAS podem ser estruturadas de maneira temática, especializando-se no atendimento de um grupo populacional específico. III. O paciente mantém um vínculo com a rede, estendendo seu tratamento ao longo do tempo, em vez de ser atendido de maneira pontual. Está correto o que se afirma em","alternativas":["III, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"E"},{"numero":29,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"A Norma Operacional Básica de Recursos Humanos estabelece que, para a atenção à saúde do trabalhador do SUS, devem ser obedecidos os mesmos princípios do Sistema Único de Saúde. A esse respeito, estabeleça a relação entre os princípios listados a seguir e as iniciativas que exemplificam sua aplicação. 1. Universalidade 2. Promoção da Saúde 3. Integralidade da Atenção ( ) Programas de incentivo para redução do tabagismo, com campanhas de conscientização sobre os danos do cigarro e medidas de apoio para os que desejam parar de fumar. ( ) Inclusão de todo s os profissionais da saúde, independentemente de sua forma de contratação, em campanhas nacionais de vacinação prioritária para reduzir riscos de exposição. ( ) Inspeções conjuntas do SUS e do Ministério do Trabalho e Previdência (MTP) para avaliar cond ições de trabalho, uso adequado de Equipamentos de Proteção Individual e cumprimento das normas de segurança. A relação correta, na ordem apresentada, é","alternativas":["3 – 2 – 1.","2 – 1 – 3.","2 – 3 – 1.","3 – 1 – 2.","1 – 3 – 2"],"correta":"B"},{"numero":30,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Com relação às orientações da Política Nacional de Saúde Integral da População Negra, avalie as afirmativas a seguir. I. Incluir o quesito cor no levantamento de informações relativas à saúde da população e no estabelecimento de iniciativas e metas. II. Substituir as práticas populares e religiosas de cuidado e saúde por técnicas e protocolos de medicina avançada e baseada em evidências. III. Ampliar a participação de movimentos sociais organizados nas instâncias de controle social do sistema de saúde. Está em consonância com a Política Nacional de Saúde Integral da População Negra o que se indica em","alternativas":["III, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":"C"},{"numero":31,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"Um dos recursos de proteção contra infecções é a imunização por meio de vacinas. No Brasil, o Ministério da Saúde disponibiliza uma ampla cartela de imunizantes pelo Programa Nacional de Imunização (PNI). Ao receber as pessoas na sala de v acina, o profissional precisa estar atento ao calendário e à caderneta e/ou ao cartão de vacinação do usuário, para que possa avaliar corretamente quais vacinas e doses devem ser administradas. Nesse sentido, na avaliação da administração da vacina rotavír us humano G1P [8] (atenuada) – VRH, para uma criança com quatro meses de idade, é correto afirmar que","alternativas":["essa criança pode tomar a 2ª dose da vacina, pois na avaliação da caderneta verificou -se que ela tomou a 1ª dose aos dois meses de idade.","se, na a dministração da 2ª dose, a criança cuspir, será necessário reaplicar a dose.","essa vacina é a única que pode ser administrada diante de quadro agudo de gastroenterite, pois ela atua para a resolução desse tipo de quadro.","essa vacina só pode ser admi nistrada a partir dos seis meses de idade.","essa vacina não faz parte do calendário, sendo administrada apenas quando há surtos"],"correta":"A"},{"numero":32,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Do conjunto de ações que formam a vigilância em saúde, a vigilância epidemiológica desempenha um papel c rucial no monitoramento de enfermidades que podem acometer a população, a exemplo de doenças transmissíveis e epidemias. A influenza sazonal é uma i nfecção viral aguda do sistema respiratório, que apresenta alta transmissibilidade. A respeito dessa doença, avalie as afirmativas a seguir. I. Entre os sintomas da síndrome gripal estão a tosse seca, a mialgia e a prostração. II. Pelo risco de complicações respiratórias, a vacina influenza trivalente, disponível nos serviços públicos de vacinação, é indicada para crianças a partir do primeiro mês de vida até cinco anos, e também para gestantes. III. No contexto da Vigilância Sentinela da Influenza, a síndrome gripal se caracteriza por indivíduo com febre, mesmo que referida, acompanhada de tosse ou do r de garganta e com início dos sintomas nos últimos sete dias. IV. No caso dos vírus respiratórios como o vírus influenza, são feitas coletas “aleatórias” de amostras clínicas de pacientes com síndrome gripal. Estão corretas apenas as afirmativas","alternativas":["I, II e IV.","II e IV.","I, II e III.","I, III e IV.","I e II"],"correta":"D"},{"numero":33,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"O Centro de Atenção Psicossocial (CAPS) é um dos serviços de referência para o cuidado com as pessoas que têm Transtornos do Espectro do Autismo (TEA). Como parte da equipe de profissionais de saúde, o enfermeiro desenvolve ações de cuidado com as pessoas que têm TEA e suas famílias. Sobre esse tema, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Um Projeto Terapêutico Singular (PTS), voltado à pessoa com TEA, deve considerar ações que estimulem a sua autonomia e independência cotidiana. ( ) Entre as tecnologias recomendadas no cuidado com as pessoas que têm TEA, a enfermeira pode aplicar a comun icação suplementar e alternativa, tais como gestos, símbolos e figuras. ( ) No caso de pessoas com TEA, o PTS deve ser construído com a família, sem a participação da pessoa com TEA, pois o processo de construção pode acarretar crises dissociativas. ( ) No caso de a pessoa com TEA usar psicofármacos, a enfermeira deve incluir no planejamento e nas ações de cuidado a orientação sobre os efeitos colaterais e, se for o caso, ajudar na escolha dos melhores horários para o uso dos medicamentos. As afirmativas são, respectivamente,","alternativas":["V – V – V – F.","V – V – F – V.","F – F – V – V.","V – F – F – V.","F – V – V – F."],"correta":"B"},{"numero":34,"disciplina":"Enfermagem","assunto":"Atenção Primária à Saúde","enunciado":"A saúde é um conceito complexo que envolve diferentes dimensões que se inter -relacionam: biológicas, psicológicas e sociais. A promoção da saúde integral abrange a compreensão do funcionamento da Rede de Atenção Psicossocial (RAPS) e o domínio sobre os transtornos e cuidados voltados à saúde mental. Sobre o atendimento e o cuidado com as pessoas em relação à saúde mental, avalie os procedimentos a seguir. I. De acordo com o protocolo clínico e as diretrizes terapêuticas do Transtorno Afetivo Bipolar do tipo I (TAB), do Ministério da Saúde (2016), o TAB é um transtorno de humor e é uma doença crônica que compromete a qualidade de vida do paciente. Entre as intervenções psicossociais que fazem parte da reabilitação do paciente, o enfermeiro deve incluir no atendimento: a discussão dos sinais precoces de recaída, as medidas a serem tomadas nessa situação e o ensino de técnicas de controle do estresse. II. Um paciente com Transtorno Esquizoafetivo está em tratamento medicamentoso com Risperidona, em doses de 3 mg, duas vezes ao dia. O frasco disponível na farmácia tem 30 mL com 1 mg/mL. Para o período de 30 dias, a enferm eira explicou ao paciente que ele precisará de seis frascos. III. No atendimento ao paciente em sofrimento psíquico e a seu familiar, a enfermeira aplicou a Teoria das Relações Interpessoais de Hildegard Peplau, em suas quatro fases. Na segunda fase, que t rata da identificação, ela selecionou a assistência profissional aplicada ao caso. IV. De acordo com o Instrutivo Técnico da RAPS do SUS (2022), os leitos em hospitais especializados em psiquiatria (hospitais psiquiátricos) devem atender a crises e agudiza ções, em internações de curta permanência (inferior a 90 dias), excluindo-se as situações de urgência/emergência relativas ao consumo ou abstinência de álcool, crack e outras drogas, pois para tais situações os pacientes devem ser encaminhados para os leitos de Unidades de Referência Especializada em Hospital Geral. Os procedimentos corretos são apenas","alternativas":["II, III e IV.","II e III.","I, II e III.","II e IV.","I, II e IV"],"correta":"C"},{"numero":35,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"Na consulta de enfermagem à criança, o acompanhamento dos sinais vitais e do crescimento e desenvolvimento são feitos seguindo-se as recomendações do Ministério da Saúde, com registros na Caderneta da Criança. Sobre os proce dimentos relativos a esses acompanhamentos, é correto afirmar que","alternativas":["o Índice de Massa Corporal (IMC) em crianças deve ser medido por meio do peso em quilograma (kg) dividido pelo valor da estatura em metros (m), expresso na seguinte fórmula: IMC = peso/estatura.","nas consultas de rotina, a medida da pressão arterial é obrigatória apenas a partir dos 5 anos de idade, tanto para meninas como para meninos.","na aferição do peso de crianças menores de 2 anos em balança pediátrica eletrônica (digital), a criança deve estar obrigatoriamente despida e deitada, pois se ela for posta sentada a precisão da medição fica comprometida.","a medida do perímetro cefálico deve ser aferida desde o nascimento e até o primeiro ano de vida e, a partir dessa idade, torna-se obrigatória apenas na presença de diagnóstico de microcefalia.","crianças menores de 2 anos devem ser medidas deitadas (comprimento); crianças com 2 anos ou mais devem ser medidas em pé (estatura)"],"correta":"E"},{"numero":37,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Na assistência de enfermagem à gestante, o enfermeiro precisa estar atento à própria gestante, às pessoas que a acompanham e ao ambiente, de modo a oferecer um momento seguro e acolhedor. Espera-se que a experiência da mulher e de sua família seja a melhor possível e que o processo transcorra sem intercorrências. Em relação ao conjunto de atividades inerentes ao cuidado com a mulher gestante para que haja uma boa vivência do parto vaginal, é correto afirmar que","alternativas":["sobre a assepsia para o parto vaginal, havendo necessidade de limpeza vulvar e perineal antes do exame vaginal, deve -se evitar água potável e optar por água estéril para evitar contaminação, caso haja necessidade de episiotomia.","a assepsia indicada para o parto vaginal é recom endada com higiene padrão das mãos e uso de luvas necessariamente estéreis para reduzir a contaminação cruzada entre as mulheres, as crianças e os profissionais.","caso opte por receber massagem que tenha sido ensinada a(os) seu(s) acompanhante(s), a mul her deve ser apoiada nesta opção durante o trabalho de parto.","acupuntura é uma técnica não farmacológica contraindicada às mulheres durante o trabalho de parto.","a dieta durante o trabalho de parto envolve o jejum, inclusive de líquidos"],"correta":"C"},{"numero":38,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"O aleitamento materno é uma estratégia eficaz para a redução da morbimortalidade infantil. No atendimento do binômio mãe-bebê, o enfermeiro assume um papel importante, com protagonismo e autonomia na consulta ao realizar o processo de enfermagem e dar enfoque ao aleitamento. Sobre a consulta de enfermagem à mulher em fase de amamentação, avalie se as seguintes orientações devem constar do plano de cuidados: I. não há comprovação de que alguma comida ou bebida que a mãe ingira possa causar cólicas no bebê; II. o descanso influencia na produção de leite da mulher; III. caso o bebê não consiga sugar a mama, o enfermeiro deve ensinar à mãe a técnica de retirada do leite do peito com as mãos ou com uma bomba, para oferecer ao bebê na colher; IV. a chupeta pode ser utilizada porque não influencia na tendência da criança em mamar por mais ou menos tempo. Estão corretas as orientações","alternativas":["I, II e III.","II e IV, apenas.","III e IV, apenas.","II e III, apenas.","I e II, apenas"],"correta":"A"},{"numero":39,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Há métodos diagnósticos que devem ser feitos no período da consulta para possibilitar decisões rápidas e seguras que conduzam à feitura de um plano terapêutico e de cuidados adequados à situação clínica do usuário. No atendimento de enfermagem, a enferm eira se deparou com a seguinte situação: F.L.Z., 35 anos, sexo masculino, solteiro, bissexual. Relatou ter mantido relação sexual casual com outro homem, de forma desprotegida, há pouco mais de 48 horas. Compareceu ao serviço de saúde para solicitar a PEP (Profilaxia Pós-Exposição), pois conhece várias pessoas que a usam para reduzir o risco de se infectar com alguma IST (Infecção Sexualmente Transmissível) e/ou com o vírus da Aids. No âmbito da consulta, a enfermeira forneceu algumas explicações para dar ampla ciência sobre seu caso e sobre o atendimento. Com base nesse histórico e no tema tratado, avalie as afirmativas a seguir. I. Ainda que esteja disponível, no caso de F.L.Z. não está indicado o uso de PEP, pois este tipo de profilaxia deve ser instituído em até 48 horas após a exposição. II. A decisão pelo uso da PEP dependerá do status sorológico para HIV, a ser avaliado por meio de testes rápidos (TRs). III. Para uma pessoa com a história de F.L.Z., que compareça à unidade de saúde dentro da janela de tempo prevista no protocolo do Ministério da Saúde (MS) e cujo teste rápido é não reagente para o HIV no momento do atendimento, a PEP está indicada. IV. Pelo histórico apresentado e pelo fato de a relação sexual ter sido casual, o tipo de profilaxia indic ada é a PrEP (Profilaxia Pré-Exposição) a ser aplicada por sete dias consecutivos, a contar do dia da consulta. As afirmativas a serem consideradas no atendimento do usuário F.L.Z. são","alternativas":["I, II e IV.","I e IV, apenas.","II e IV, apenas.","I e II, apenas.","II e III, apenas."],"correta":"E"},{"numero":40,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Alterações no clima do planeta têm sido um tema preocupante e vêm ocupando as agendas dos líderes mundiais e de vários segmentos sociais. Esses eventos ameaçam a vida e geram múltiplos problemas, mobilizando debates para a proposição de políticas e programas, em especial na saúde pública. Grandes enchentes e ondas de calor são consequências atribuídas às alterações climáticas. Nessas situações, problemas de saúde física e mental são pontos de atenç ão dos governantes e dos profissionais de saúde. Para o caso de eventos que envolvam alterações climáticas, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A leptospirose é uma doença infecciosa preocupante, pois a lama de enchentes tem alto poder infectante. A transmissão se dá por meio da exposição à urina de animais infectados quando a pessoa possui lesões na pele. Com a pele íntegra não há risco de infecção. ( ) Para evitar o tétano acidental, a pessoa deve acessar os lugares acometidos por enchentes usando botas e luvas. Em caso de ferimento durante ou após uma enchente, deve -se verificar a data da última dose da vacina e, se for necessário, procurar o serviço de saúde/profissional de saúde para avaliar a necessidade de reforço. ( ) Ondas de calor são eventos cada vez mais frequentes e a intensa exposição ao sol pode causar problemas de variados graus de gravidade. Uma pessoa com transpiração, fraqueza, tonturas, desmaios, náuseas, dor de cabeça, cãibras musculares e diarreias pode estar sofrendo de exaustão térmica. No caso de insolação, entre as medidas de primeiros socorros estão a aplicação de compressas de água fria na testa, pescoço, axilas e virilhas e, se possível, deve -se borrifar delicadamente água fria em todo o corpo da pessoa. ( ) No atendimento na unidade de saúde de um paciente de 25 anos, sexo masculino, que enfrentou uma enchente em casa e apresenta doença diarreica aguda, deve -se fazer a avaliação do estado de hidratação do paciente. Consta tada a desidratação, deve-se administrar continuamente a solução de sais de reidratação oral, até que desapareçam os sinais de desidratação. No plano de educação em saúde devem constar as medidas de higiene pessoal, domiciliar e dos alimentos. As afirmativas são, respectivamente,","alternativas":["F – V – F – V.","V – F – V – F.","F – V – F – F.","F – V – V – V.","V – F – F – V"],"correta":"D"},{"numero":41,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Organização e Competências","enunciado":"Sobre os objetivos e atribuições do Sistema Único de Saúde (SUS), conforme estabelecido pela Lei Orgânica de Saúde (LOS), avalie as afirmativas a seguir. I. Compete ao SUS a fiscalização e a inspeção de alimentos para consumo humano, exceto o de água e bebidas, pois esta fiscalização é de responsabilidade de outro sistema. II. Entre os objetivos do SUS está a assistênci a às pessoas por intermédio de ações de promoção, proteção e recuperação da saúde, com a realização integrada das ações assistenciais e das atividades preventivas. III. O campo de atuação do SUS inclui a execução de ações de vigilância sanitária, de vigilâ ncia epidemiológica, de saúde do trabalhador, de assistência terapêutica integral, inclusive farmacêutica, e de saúde bucal. IV. Compete ao SUS a formulação da política de medicamentos, equipamentos, imunobiológicos e outros insumos de interesse para a saúde e a participação na sua produção. Estão corretas apenas as afirmativas","alternativas":["I e II.","I e III.","II, III e IV.","I, II e III.","I, III e IV"],"correta":"C"},{"numero":42,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"Auditoria em enfermagem é a avaliação sistemática da qualidade da assistência em enfermagem, verificada por intermédio das anotações no prontuário do paciente e/ou das próprias condições do prontuário. A auditoria surge como a fase final do processo de planejamento da assistência de enfermagem, que é imprescindível à pre stação de uma assistência adequada e de qualidade ao indivíduo. Sobre os tipos de auditoria, assinale a afirmativa correta.","alternativas":["Auditoria operacional é feita em 10% dos prontuários de uma instituição para buscar dados que não foram anotados durante a realização da auditoria retrospectiva.","Auditoria retrospectiva é feita após a alta do paciente, em que se utiliza o prontuário para avaliação, portanto, os dados obtidos não beneficiarão aquele paciente diretamente, mas para auxiliarão na assistência de maneira global.","Auditoria concorrente é feita em 50% dos prontuários de uma instituição para buscar dados que não foram anotados quando foi realizada a auditoria retrospectiva.","Auditoria operacional é feita em 50% dos prontuários de uma instituição para buscar dados que não foram anotados durante a realização da auditoria retrospectiva e dispensa a realização de um plano auditorial.","Auditoria retrospectiva dispensa a realização de um plano auditorial e a elaboração de um relatório final, pois essas exigências são feitas apenas para a auditoria concorrente ou operacional."],"correta":"B"},{"numero":43,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"O traumatismo cranioencefálico pode provocar condições que variam desde uma concussão leve até o coma e a morte. Sua forma mais grave é conhecida como lesão cerebral traumática (LCT). As causas mais comuns de LCT são as quedas, os acidentes com veículos motorizados, a colisão de objetos e os assaltos. Sobre a assistência do enfermeiro ao paciente com traumatismo cranioencefálico, é correto afirmar que","alternativas":["uma leitura da Escala de Coma de Glasgow entre 3 e 8 é considerada como indicativa de traumatismo cranioencefálico grave, sendo recomendada a intubação orotraqueal.","a Escala de Coma de RASS serve de guia para avaliar o nível de consciência do paciente com base em três critérios: abertura dos olhos, respostas verbais e respostas motoras.","a Escala de Coma de Ramsay serve de guia para avaliar o nível de consciência do paciente com base em três critérios: abertura dos olhos, respostas verbais e respostas motoras.","na Escala de Coma de Glasgow, para avaliar o nível de consciência do paciente, um escore de 15 é menos responsivo, enquanto um escore de 3 é mais responsivo.","na Escala de Coma de RASS, para avaliar o nível de consciência do paciente, um escore de 15 é menos responsivo, enquanto um escore de 3 é mais responsivo"],"correta":"A"},{"numero":44,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Atualmente, câncer é o nome geral dado a um conjunto de mais de 100 doenças que têm em comum o crescimento desordenado de células que tendem a invadir tecidos e órgãos vizinhos. De acordo com a cartilha ABC do Câncer, publicada em 2020 pelo Ministério da Saúde, existem três formas principais de tratamento do câncer: cirurgia, radioterapia e quimioterapia, que podem ser usadas em conjunto, variand o apenas quanto à suscetibilidade dos tumores a cada uma das modalidades terapêuticas e à sequência ideal de sua administração. Sobre esses tratamentos, avalie as afirmativas a seguir. I. A radioterapia pré -operatória (prévia ou citorredutora) é o procedimento que antecede a principal modalidade de tratamento, a cirurgia, para reduzir o tumor e facilitar o procedimento operatório. II. A quimioterapia curativa tem a finalidade de curar pacientes com neoplasias malignas para os quais representa o principal tratamento, podendo ou não estar associada à cirurgia e à radioterapia. III. Uma das competências privativas do enfermeiro em quimioterapia antineoplásica é planejar, organizar, supervisionar, executar e avaliar todas as atividades de enfermagem, em pacient es submetidos ao tratamento quimioterápico antineoplásico, categorizando -o como um serviço de alta complexidade. IV. Radioterapia pós -operatória ou pós -quimioterapia (profilática): segue-se à principal modalidade de tratamento, com a finalidade de esterili zar possíveis focos microscópicos do tumor. As afirmativas corretas são","alternativas":["I, III e IV, apenas.","I, II e IV, apenas.","II, III e IV, apenas.","I, II, III e IV.","III e IV, apenas"],"correta":"D"},{"numero":45,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"As recomendações para Suporte Básico de Vida (SBV) e para Suporte Avançado de Vida Cardiovascular (SAVC) estão combinadas nas diretrizes da American Heart Association (AHA) publicadas em 2020. Sobre as principais novas alterações de SBV e SAVC em adultos, avalie as afirmativas a seguir. I. O atendimento do paciente após o retorno da circulação espontânea requer muita atenção à oxigenação, ao controle da pressão arterial, à avaliação da intervenção coronária percutânea, ao controle direcionado de temperatura e ao neuroprognóstico multimodal. II. O acesso intraósseo é a via de primeira escolha de administração de medicação durante a ressuscitação no SAVC. III. Mensurar continuamente a pressão arterial sanguínea e o teor de dióxido de carbono ao final da expira ção durante a ressuscitação de SAVC pode ser útil para melhorar a qualidade da reanimação cardiopulmonar. IV. As recomendações anteriores da AHA sobre a administração de epinefrina foram reafirmadas, com ênfase em sua administração mais precoce. As afirmativas corretas são","alternativas":["I, II e III, apenas.","I, III e IV, apenas.","II, III e IV, apenas.","I, II e IV, apenas.","I, II, III e IV"],"correta":"B"},{"numero":46,"disciplina":"Enfermagem","assunto":"Hipertensão Arterial","enunciado":"Uma mulher de 55 anos foi admitida na clínica médica de um hospital com um quadro grave de crise hipertensiva já estabilizado, mas ainda em uso de medicações venosas. Ao exame físico, o enfermeiro identifica a presença de uma fístula arteriovenosa no membro superior direito com frêmito tátil para as sessões de hemodiálise e a necessidade de um novo acesso venoso periférico. Em relação ao atendimento a essa paciente, é correto afirmar que","alternativas":["o enfermeiro deve realizar a punção venosa para a administração das medicações anti-hipertensivas no membro superior direito, já que essa prática não afeta o acesso para hemodiálise.","o enfermeiro deve ter cautela com os acessos periféricos no membro superior direito, que apresenta a fístula arteriovenosa, mas devido à necessidade de controle rigoroso da pressão arterial, a medição deve ser alternada entre os membros superiores.","o enfermeiro deve realizar a punção venosa na própria fístula para não sobrecarregar a rede venosa da paciente.","o membro superior direito pode ser utilizado para a punção venosa, desde que a veia escolhida seja próxima da fístula arteriovenosa.","o enfermeiro deve evitar a punção venosa e a medição da pressão arterial no membro com a fístula arteriovenosa, preferindo realizar esses procedimentos no membro superior esquerdo."],"correta":"E"},{"numero":47,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Em uma unidade de emergência o enfermeiro de plantão atende um paciente de 58 anos, sexo masculino, com queixa de dor torácica que irradia para o membro superior esquerdo, apresentando pele fria, pálida e úmida, frequência cardíaca e frequência respiratória aumentadas, quando comparadas ao padrão normal para a faixa etária. Sobre esse atendimento, avalie as afirmativas a seguir. I. No exame físico o enfermeiro deve avaliar o nível de consciência, as bulhas cardíacas, a pressão arterial, os pulsos periféricos, auscultar os campos pulmonares, avaliar a motilidade intestinal, observar o débito urinário e verificar a existência de edema. II. O enfermeiro deve coletar dados iniciais sobre o estado atual do paciente e compará -los com a evolução do quadro clínico. Isso inclui investigar a história de dor ou desconforto torácico, dispneia, palpitações, fadiga incomum, síncope ou outros sinais que possam indicar isquemia miocárdica. III. O enfermeiro deve realizar um exame mais focado em sinais e sintomas relacionados às doenças do aparelho respiratório, como a asma, e solicitar ao médico prescrição de broncodilatadores para melhorar a dor torácica e os sinais vitais alterados. Está correto apenas o que se afirma em","alternativas":["I e III.","II e III.","III.","I.","I e II"],"correta":"E"},{"numero":48,"disciplina":"Legislação do COFEN","assunto":"Responsabilidade Profissional","enunciado":"A Resolução Cofen nº 710/2022 atualiza a norma técnica referente à atuação da equipe de enfermagem no processo de doação, captação e transplante de órgãos, tecidos e células. Sobre essa atuação, avalie as afirmativas a seguir. I. Compete privativamente ao enfermeiro planejar, coordenar, executar, supervisionar e avaliar as ações do técnico de enfermagem, prestadas ao doador vivo ou falecido, a seus familiares e ao receptor, bem como ao material biológico para fins de transplante. II. A entrevista familiar, com a finalidade de doação de órgãos, tecidos e células, compete à equipe de enfermagem, podendo ser realizada pelo técnico de enfermagem ou enfermeiro. III. A assistência de enfermagem no processo de doação, captação e transplante de órgãos, tecidos e células deve seguir protocolos institucionais baseados em evidências científicas, conforme legislação vigente. Está correto o que se afirma em","alternativas":["I e II, apenas.","II e III, apenas.","I e III, apenas.","II, apenas.","I, II e III"],"correta":"C"},{"numero":49,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"No contexto do gerenciamento de enfermagem em serviços de saúde, a atuação do enfermeiro gestor envolve a coordenação de processos que assegu rem a qualidade da assistência e o bom funcionamento das equipes. Além de liderar a equipe de enfermagem, o enfermeiro desempenha a função de gerenciar estratégias de educação continuada, avaliar o desempenho dos profissionais e garantir o dimensionamento adequado do pessoal, conforme as necessidades assistenciais. Para assegurar a eficácia na gestão do processo de trabalho de enfermagem, é essencial que o enfermeiro compreenda as especificidades da liderança, avalie as condições organizacionais e aplique parâmetros técnicos na definição da carga de trabalho. Com base nesse contexto, avalie as afirmativas a seguir. I. Para que uma organização efetive a avaliação de desempenho como estratégia de desenvolvimento pessoal, é necessário que seja feito o diagnósti co situacional, ou seja, devem ser conhecidas a filosofia da organização, a dinâmica organizacional e as características dos recursos humanos. II. A estrutura administrativa que tem a educação continuada vinculada técnica e administrativamente ao departamento de enfermagem favorece para que a educação continuada tenha coordenação própria, autoridade nas próprias decisões e comunicação horizontal com as demais divisões. III. Considerando os parâmetros para o dimensionamento de enfermagem presentes no Parecer Normativo nº 1/2024 do Cofen, para efeito de cálculo, deverá ser observada a cláusula contratual adotada quanto a Carga Horária Semanal (CHS), a Taxa de Ocupação (TO) da Unidade de Internação e o Índice de Segurança Técnica (IST) de, no mínimo, 15% do total, dos quais 8,3% são referentes a férias e 6,7%, a ausências não previstas. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"E"},{"numero":50,"disciplina":"Enfermagem","assunto":"Gerenciamento de Resíduos de Serviços de Saúde (GRSS)","enunciado":"A RDC nº 222, de 28 de março de 2018, que regulamenta as boas práticas de gerenciamento dos Resíduos de Serviços de Saúde (RSS), pretende minimizar os riscos inerentes ao gerenciamento de resíduos no país no que diz respeito à saúde humana e animal, bem como à proteção ao meio ambiente e aos recursos naturais renováveis. Tendo por base essa RDC, assinale a afirmativa correta sobre o gerenciamento dos Resíduos de Serviços de Saúde (RSS).","alternativas":["Os sacos para o acondicionamento de RSS do grupo A devem ser substituídos ao atingirem o limite de 2/3 de sua capacidade ou então a cada 48 horas, independentemente do volume, visando ao conforto ambiental e à segurança dos usuários e profissionais.","O esvaziamento ou reaproveitamento dos sacos podem ser feitos quando não houver sacos suficientes na instituição.","Os sacos contendo RSS do grupo A de fácil putrefação devem ser substituídos no máximo a cada 48 horas, independentemente do volume.","Os RSS do grupo A que não precisam ser obrigatoriamente tratados e os RSS após o tratamento são considerados rejeitos e devem ser acondicionados em saco preto.","Os RSS do grupo A que obrigatoriamente precisam ser tratados devem ser acondicionados em sacos pretos."],"correta":"A"},{"numero":51,"disciplina":"Enfermagem","assunto":"Processo de Enfermagem e SAE","enunciado":"O processo de enfermagem é um mé todo que orienta o pensamento crítico e o julgamento clínico do enfermeiro direcionando a equipe de enfermagem para o cuidado. De acordo com a Resolução Cofen nº 736/2024, o objetivo da etapa de evolução de enfermagem é","alternativas":["avaliar os resultados alcançado s de enfermagem e saúde, permitindo a análise e revisão de todo o processo de enfermagem.","registrar as condições iniciais de saúde do paciente, permitindo a análise e revisão de todo o processo de enfermagem.","formular os diagnósticos de enfermagem, permitindo a análise e revisão de todo o processo de enfermagem.","implementar as intervenções de enfermagem, permitindo a análise e revisão de todo o processo de enfermagem.","realizar o registro no prontuário do paciente, permitindo a análise e revisão de todo o processo de enfermagem"],"correta":"A"},{"numero":52,"disciplina":"Legislação do COFEN","assunto":"Processo de Enfermagem","enunciado":"O processo de enfermagem deve ser realizado de forma deliberada e sistemática em todos os contextos socioambientais em que ocorre o cuidado de enfermagem. De acordo com a Resolução Cofen nº 736/2024, na etapa de planejamento de enfermagem, há elementos que devem ser considerados para o desenvolvimento de um plano assistencial eficaz, direcionado ao paciente, à família, à coletividade ou aos grupos especiais e compartilhado com a equipe de saúde. Avalie se tais elementos incluem: I. priorização de diagnósticos de enfermagem; II. determinação de resultados esperados e exequíveis de enfermagem e de saúde; III. tomada de decisão terapêutica, declarada pela prescrição de enfermagem das intervenções, ações/atividades e protocolos assistenciais; IV. priorização da prescrição médica. Estão corretos os itens","alternativas":["II, III e IV, apenas.","I, II e III, apenas.","I, II, III e IV.","I e IV, apenas.","III e IV, apenas"],"correta":"B"},{"numero":53,"disciplina":"Enfermagem","assunto":"Centro Cirúrgico","enunciado":"Durante as etapas do período perioperatório, o enfermeiro desempenha papéis específicos para garantir a segurança e o bem- estar do paciente. Assinale a opção que descreve corretamente uma ação correspondente ao período transoperatório.","alternativas":["Orientar o paciente e sua família sobre os cuidados necessários no domicílio após a alta hospitalar.","Verificar se o paciente realizou o jejum pré -operatório conforme recomendado.","Monitorar continuamente os sinais vitais e manter a segurança do paciente durante o procedimento cirúrgico.","Avaliar a dor e administrar analgésicos no período imediato após o procedimento.","Revisar exames pré -operatórios e obter o consentimento informado"],"correta":"C"},{"numero":54,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Durante a avaliação de um paciente hospitalizado, o enfermeiro observa um padrão respiratório caracterizado por ciclos de respiração que aumentam e diminuem em profundidade, seguidos de um período de apneia. Esse tipo de respiração é comumente associado a condições como insuficiência cardía ca ou lesões cerebrais. Esse padrão respiratório denomina-se","alternativas":["respiração de Biot.","respiração de Kussmaul.","taquipneia.","respiração de Cheyne-Stokes.","apneia"],"correta":"D"},{"numero":55,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Um paciente de 48 anos com doença renal crônica (DRC) estágio 4, está internado para o acompanhamento da progressão da doença. Durante a avaliação de enfermagem, ele relata fraqueza, náuseas frequentes e apresenta edema moderado em membros inferiores. Seus exames laboratoriais revelam Hb (hemoglobina) de 8,5 g/dL e fósforo sérico (P) de 6,8 mg/dL. A conduta correta a ser tomada pelo enfermeiro é","alternativas":["verificar com o médico a necessidade de suspender a administração de eritropoetina devido ao risco de aumento da fraqueza muscular.","incentivar a ingestão de alimentos ricos em fósforo para corrigir os níveis de anemia.","aumentar a ingestão de líquidos para diluir o fósforo sérico elevado e reduzir os efeitos da hiperfosfatemia.","solicitar exames de sangue para avaliar marcadores inflamatórios.","orientar sobre restrição de alimentos ricos em fósforo e administrar quelantes de fósforo conforme prescrição médica"],"correta":"E"},{"numero":56,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"As infecções da corrente sanguínea relacionadas a cateteres centrais (ICSRC) estão associadas a importantes desfechos desfavoráveis à saúde. Nos Estados Unidos da América (EUA), a mortalidade atribuível a essa síndrome geralmente ultrapassa os 10%, podendo chegar a 25% em pacientes de maior risco. Considerando as orientações descritas no Caderno de Medidas de Prevenção de Infecção Relacionada à Assistência à Saúde da Anvisa (2017), sobre as boas práticas de flushing e a manutenção do cateter periférico, é correto afirmar que","alternativas":["a aspiração para verificar o retorno de sangue antes de cada infusão é realizada para garantir a funcionalidade do cateter e prevenir complicações.","o flushing pulsátil ( push-pause) é preferível ao flushing contínuo, pois cria um fluxo laminar que evita a deposição de resíduos no lúmen do cateter.","o uso de água estéril é recomendado para flushing e lock de cateteres periféricos em pacientes com restrição hídrica.","soluções em grandes volumes, como fra scos de soro, são adequadas para a obtenção de flushing devido ao baixo custo e acessibilidade.","seringas menores que 10 mL devem ser utilizadas para gerar maior pressão durante o flushing e garantir a desobstrução do cateter."],"correta":"A"},{"numero":57,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"A adoç ão de precauções padrão e precauções específicas por forma de transmissão é fundamental para a prevenção e o controle de infecções no ambiente hospitalar. Considerando as recomendações para a segurança individual e coletiva dos profissionais de saúde e pac ientes, assinale a afirmativa correta.","alternativas":["O uso de Equipamentos de Proteção Individual (EPIs) é opcional para os procedimentos invasivos quando o profissional de saúde já possui imunidade adquirida contra infecções comuns no ambiente hospitalar.","O iso lamento de pacientes com infecções transmitidas por gotículas requer a utilização de máscara cirúrgica por profissionais de saúde e visitantes que entram no quarto.","As precauções padrão devem ser aplicadas somente em pacientes diagnosticados com doença s infecciosas confirmadas.","A desinfecção de superfícies e equipamentos médicos é necessária apenas quando há evidências visíveis de contaminação por fluidos biológicos.","A precaução de contato exige o uso obrigatório de máscara N95 para todos os profissionais"],"correta":"B"},{"numero":58,"disciplina":"Enfermagem","assunto":"Centro de Material e Esterilização (CME)","enunciado":"A Agência Nacional de Vigilância Sanitária (Anvisa), na RDC nº 15/2012, dispõe sobre requisitos de boas práticas para o processamento de produtos para saúde. Com base nessas diretrizes, avalie as afirmativas a seguir. I. O monitoramento do processo de esterilização com indicadores físicos deve ser registrado a cada ciclo de esterilização. II. O monitoramento com indicadores físicos é opcional, sendo realizado apenas quando houver falhas nos testes químicos ou biológicos. III. O uso de indicador biológico em produtos implantáveis é obrigatório em todas as cargas, e a liberação do material só deve ocorrer após a leitura negativa do indicador. IV. O indicador biológico deve ser utilizado diariamente e posicionado no ponto mai s crítico da carga, conforme os estudos térmicos da qualificação do equipamento. Estão corretas as afirmativas","alternativas":["II e III, apenas.","I e III, apenas.","I, III e IV, apenas.","I e IV, apenas.","I, II, III e IV"],"correta":"C"},{"numero":59,"disciplina":"Enfermagem","assunto":"Saúde do Idoso","enunciado":"Um idoso de 78 a nos chega à unidade básica de saúde acompanhado por sua filha, que relata que o pai apresenta perda de interesse por atividades e dificuldade em realizar tarefas simples do dia a dia. Durante a consulta, o enfermeiro identifica que o paciente apresenta len tidão ao caminhar e sinais de perda de peso recente. A ação prioritária na avaliação inicial do enfermeiro, considerando as síndromes geriátricas, é iniciar com a","alternativas":["identificação de sinais de desnutrição e realizar uma avaliação nutricional completa.","investigação de sinais de depressão utilizando um instrumento de rastreio validado.","avaliação de sinais de comprometimento cognitivo para investigar demência.","realização de triagem para síndrome da fragilidade.","avaliação do risco de quedas utilizando uma escala apropriada"],"correta":"D"},{"numero":60,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Durante a ausculta cardíaca de um paciente, o enfermeiro posiciona o estetoscópio no quinto espaço intercostal, na linha médio-clavicular esquerda. A válvula cardíaca que está sendo avaliada nesse local é","alternativas":["o foco de Erb (ou Terceiro Foco).","a pulmonar.","a tricúspide.","a aórtica.","a mitral."],"correta":"E"}]},{"codigo":"ebserh-psicologia-gp12","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/grupo-12-psicologiae3cnsgp12-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/ebserrhassistencial2024_gabarito_definitivo.pdf","cargo":"Psicologia — saúde mental","orgao":"EBSERH","ano":2025,"questoes":[{"numero":31,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Nise da Silveira foi uma psiquiatra que revolucionou o tratamento da doença mental no Brasil com uma abordagem que valorizava a expressão das emoções, a atividade artística e o contato com animais. O trabalho de Nise da Silveira teve como inspiração","alternativas":["a Gestalt-terapia de Fritz Perls.","o psicodrama de Jacob Moreno.","a psicologia analítica de Carl Gustav Jung.","a psicanálise humanista de Erich Fromm.","a abordagem centrada na pessoa de Carl Rogers"],"correta":"C"},{"numero":33,"disciplina":"Enfermagem","assunto":"Saúde do Idoso","enunciado":"A trajetória do jornalista Maurício Kubrusly é o tema de um documentário em que se retrata momentos de sua rotina a partir do diagnóstico da doença neurológica que o acometeu. Sobre essa condição é possível apontar que","alternativas":["a demência frontotemporal tem como característica principal o surgimento de sintomas psicóticos e/ou depressivos em pacientes que apresentavam um funcionamento normal.","a demência frontotemporal é um transtorno do neurodesenvolvimento degenerativo e incapacitante que acomete preferencialmente pessoas idosas.","transtorno cognitivo frontotemporal ou demência senil é uma das manifestações neurológicas e clínicas da doença de Alzheimer.","mudanças de comportamento e/ou declínio da capacidade linguística são critérios para o diagnóstico do transtorno neurocognitivo frontotemporal.","o transtorno neurocognitivo frontotemporal é tratável e pode até regredir com terapêutica adequada desde que diagnosticado em estágios precoces"],"correta":"D"},{"numero":34,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Débora desenvolveu um quadro de fobia a elevadores desde que ficou presa em um elevador que sofreu uma pane elétrica. Ela passou a contornar esse problema usando as escadas dos prédios, mas acaba de ser transferida para uma seção que funciona no 12º andar. Débora buscou a Terapia Cognitivo -Comportamental para lidar com essa limitação e uma das técnicas empregadas por seu terapeuta foi a dessensibilização sistemática. A dessensibilização sistemática consiste","alternativas":["na imersão da paciente em situações que buscam reconstituir a situação original ansiogênica.","no questionamento socrático dos pensamentos disfuncionais automáticos que desencadeiam a fobia.","no treino mediado pelo terapeuta para o desenvolvimento de habilidades sociais e assertividade na comunicação.","na explicação em linguagem acessível à paciente sobre o funcionamento do psiquismo após a vivência de situações traumáticas.","na exposição gradual e controlada da paciente aos estímulos geradores de ansiedade e uso de técnicas de relaxamento"],"correta":"E"},{"numero":36,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Marcelo é médico intensivista em um grande hospital público e trabalha, sob grande pressão, com pacientes críticos. Em uma ocasião, padecendo de dores de cabeça e estressado, com um longo plantão pela frente, Marcelo se prescreveu um opioide que lhe trouxe imediato alívio e sensação de grande bem-estar. Marcelo passou a fazer uso eventual, mas foi paulatinamente intensificando o uso, a ponto de forjar receitas na tentativa de despistar o controle da farmácia do hospital para obter mais comprimidos da substância. Sobre a situação que Marcelo atravessa, é correto apontar que","alternativas":["a tolerância à substância psicoativa se manifesta pela necessidade de aumentar progressivamente a dosagem usada para alcançar o efeito esperado.","a abstinência se caracteriza pela sensação de superação do vício ao final do longo processo de desintoxicação química.","a intoxicação pela substância psicoativa é uma reação crônica que acontece pelo uso cumulativo da substância estimulante.","Marcelo pode reduzir os danos da ingestão dos opioides combinando seu uso com o de substâncias que agem como antídoto.","as chances de Marcelo desenvolver uma dependência química de opioides são menores pelo fato de ele, como médico, deter um conhecimento técnico quanto aos riscos do uso e do abuso"],"correta":"A"},{"numero":37,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Programas de saúde mental em empresas podem promover o bem-estar emocional dos funcionários, prevenir o estresse e reduzir o impacto de transtornos mentais no ambiente de trabalho. As opções a seguir dão exemplos de programas de saúde mental que podem ser desenvolvidos no ambiente laboral contemplando o bem estar dos colaboradores, à exceção de uma. Assinale-a.","alternativas":["Programas de preparação dos funcionários para a aposentadoria.","Workshops de gerenciamento de estresse e desconexão digital.","Oferta de espaços de escuta ativa e acolhimento psicológico confidencial.","Programas de incentivo à ‘pejotização’ e à autonomia profissional dos colaboradores.","Palestras educativas sobre temas em saúde mental como tabagismo, alcoolismo e depressão"],"correta":"D"},{"numero":38,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"A seguinte técnica de entrevista e abordagem de tratamento, idealizada originalmente para pacientes com dependência química, e hoje empregada também em uma série de situações em que favorecer a adesão do paciente ao tratamento é muito importante, como em t ranstornos alimentares e cessação do tabagismo é","alternativas":["o modelo de recompensa.","a entrevista dirigida.","a entrevista psicodinâmica.","a troca de papéis ou role playing.","a entrevista motivacional"],"correta":"E"},{"numero":39,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Bruno, 55 anos, bancário, procurou o pronto-atendimento de uma unidade hospitalar apresentando sintomas de exaustão física e mental, pressão alta, distúrbios gastrointestinais, humor depressivo. O médico diagnosticou a Síndrome de Burnout e recomendou um afastamento do trabalho; porém, temendo ser dispensado, Bruno continuou comparecendo ao trabalho e já vê sua produtividade impactada pela dificuldade de concentração. Identifica-se nesse relato uma situação de","alternativas":["rotatividade.","presenteísmo.","ergonomia ambiental.","retenção de talentos.","absenteísmo"],"correta":"B"},{"numero":40,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"O psicólogo Eduardo integra uma equipe interprofissional na empresa de prestação de serviços na área da saúde em que trabalha. Sobre o funcionamento de uma equipe com esse perfil é possível afirmar que, na interprofissionalidade,","alternativas":["a coordenação da equipe é exercida em rodízio de forma democrática, cabendo ao coordenador a palavra final quanto à definição da estratégia de atuação entre as sugeridas.","existem reuniões de equipe, mas cada profissional atua de forma independente e todos se reportam a um líder hierarquicamente superior na estrutura da empresa.","verifica-se uma diluição entre as competências das diferentes categorias profissionais de forma que seus papéis se tornam indistinguíveis.","profissionais de diferentes formações trabalham de forma horizontal e colaborativa, trocando informações para uma atuação conjunta em benefício do cliente.","as reuniões são agendadas quanto surge uma demanda específica de forma a otimizar o tempo dos colaboradores e focar em resultados"],"correta":"D"},{"numero":44,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Paula Benedita é psicóloga concursada de um pequeno município do interior que foi fortemente castigado por intensas chuvas e enchentes. Psicólogos, médicos e enfermeiros da Prefeitura foram chamados para atuar no atendimento das famílias afetadas. Diante da situação hipotética, o profissional","alternativas":["deve recusar a convocação pois trabalha com psicologia escolar na Secretaria de Educação da Prefeitura.","deve prestar o serviço profissional nessa situação de calamidade pública.","deve esperar pela convocação do Conselho de Psicologia Regional para atuar na emergência.","precisa se capacitar primeiro para atender dinâmicas que envolvam catástrofes e emergências.","pode atender à convocação desde que o serviço conte horas extras de trabalho"],"correta":"B"},{"numero":45,"disciplina":"Saúde Coletiva I","assunto":"Educação Permanente em Saúde","enunciado":"Com relação à educação em saúde, avalie as afirmativas a seguir. I. É circunscrita à formação de profissionais na área da saúde. II. Objetiva produzir melhorias na qualidade de vida do indivíduo e no fortalecimento da população como um todo. III. É um conjunto abrangente de ações que promove conhecimentos, comportamentos e práticas saudáveis. Está correto apenas o que se afirma em","alternativas":["I, apenas.","II, apenas.","III, apenas.","I e II, apenas.","II e III, apenas"],"correta":"E"},{"numero":46,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"O modelo de atenção proposto pelo SUS exige a criação de estratégias que vão além dos cuidados individuais para o atendimento das necessidades de saúde da população. Nesse sentido, a formação de grupos na Atenção Básica constitui","alternativas":["espaço importante no qual as pessoas possam falar sobre a vivência do adoecimento ou condição de vida e das maneiras que encontraram de agir no cotidiano, criando novas formas de superação dos seus problemas.","local de reprodução do modelo hospitalocêntrico, em que a figura do gestor da instituição é apresentada como autoridade do processo de promoção e produção da saúde, ao qual os membros do grupo devem se submeter.","espaço para diagnóstico médico, composto predominantemente por médicos e enfermeiros, dos problemas comuns que afetam a população brasileira, tais como diabetes e hipertensão arterial.","lugar em que são ensinados os conhecimentos corretos para manejo de doenças físicas e psíquicas que afetam à população, com ênfase no manejo acadêmico dos saberes biomédicos e nutricionais.","porta de entrada para demanda espontânea na unidade de saúde, incentivando o aumento de procura por atendimento das pessoas com problemas crônicos e agudos"],"correta":"A"},{"numero":48,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Acerca da terapia familiar sistêmica, avalie as afirmativas a seguir. I. Centra-se na família como um todo, não a considerando como uma mera soma das suas partes, pois tudo o que acontece num elemento irá afetar os outros elementos. II. A família é um sistema aberto em interação com outros sistemas (escola, emprego, bairro). III. A família é um sistema em constante transformação que se adapta às exigências das diversas fases de seu ciclo de desenvolvimento por meio do equilíbrio dinâmico entre a tendência homeostática e a capacidade de transformação. Está correto o que se afirma em","alternativas":["I, apenas.","II e III, apenas.","I e III, apenas.","I e II, apenas.","I, II e III."],"correta":"E"},{"numero":49,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Reginaldo tem 35 anos e sempre apresentou comportamentos impulsivos, extrema dificuldade em regular suas emoções, momentos em que se automutilou e episódios em que desenvolveu crenças delirantes. Segundo o DSM 5, os comportamentos de Reginaldo podem ser sugestivos de","alternativas":["transtorno de personalidade esquizoide.","depressão maior.","perturbação de personalidade evitante.","transtorno de personalidade borderline.","transtorno obsessivo compulsivo"],"correta":"D"},{"numero":50,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"A aprendizagem nas empresas é um processo dinâmico e contínuo de aquisição, compartilhamento e aplicação de conhecimentos que visam à melhoria de seus desempenhos e à adaptação às transformações que as cercam. Júlio trabalha há 5 anos na área de marketing da empresa Preparando Alimentos e participou de uma capacitação programada com a equipe da cozinha para desenvolver um projeto de inovação das receitas da empresa. O relato fala de","alternativas":["aprendizagem solitária.","aprendizagem solidária.","aprendizagem interdepartamental.","capacitação ecológica.","treinamento sustentável"],"correta":"C"},{"numero":55,"disciplina":"Saúde Coletiva I","assunto":"Promoção da Saúde","enunciado":"Os estudos de caso são bastante empregados como ferramenta metodológica na pesquisa em psicologia, de modo que atualmente podem ser apontados como uma das estratégias mais frequentes. Com relação ao estudo de caso, analise as afirmativas a seguir. I. O estudo de caso tem como pressuposto metodológico o princípio de que o conhecimento é algo em constante (re)construção. II. Os “estudos de caso exploratórios” têm como meta a descoberta de novas áreas de pesquisa ou o delineamento de novas abordagens para objetos pouco conhecidos. II. Os “estudos de caso observacionais” utilizam a observação como técnica de coleta de dados principal e permitem ao pesquisador um contato próximo com o ambiente no qual seu objeto encontra-se inserido. Está correto o que se afirma em","alternativas":["I, apenas.","III, apenas.","I e II, apenas.","II e III, apenas.","I, II e III"],"correta":"E"},{"numero":56,"disciplina":"Saúde Coletiva I","assunto":"Determinação Social da Saúde","enunciado":"Spink (2003) destaca que o trabalho do(a) psicólogo(a) junto aos cenários da saúde, suas respectivas populações e instituições implica diversos desafios éticos. Tendo em vista tais contextos, um dos objetivos da atuação do psicólogo(a) é","alternativas":["construir estimativas de risco de doenças mentais crônicas para delinear estratégias educativas.","possibilitar que os usuários de um determinado território se transformem em sujeito de psicoterapia.","compreender os significados que o processo saúde -doença tem para o sujeito e para os grupos sociais.","permitir que o saber popular seja totalizado pelos saberes oficiais, enfatizando o discurso científico.","contribuir para a normalização de sujeitos e coletivos por meio da promoção do bem-estar biopsicossocial"],"correta":"C"},{"numero":58,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Os saberes médicos ocupam uma posição hegemônica no campo de drogas contemporâneo, influenciando políticas públicas e ofertas assistenciais e preventivas da dependência de substâncias psicoativas. Com relação à influência dos saberes médicos nessa área, é correto afirmar, de uma forma crítica, que","alternativas":["fundamentam uma perspectiva questionadora quanto à normatização dos comportamentos dos usuários.","são amparados no conhecimento do sistema neurológico e da genética e defendem a autonomia dos usuários.","compõem a articulação de três formações discursivas, sendo elas a medicalização, a criminalização e a moralização dos usuários.","compreendem a dependência de drogas como um problema de personalidade, sendo consenso a defesa da redução de danos.","consideram que o uso compulsivo de drogas tem a função de redefinir a representação do corpo na dinâmica psíquica, valorizando as psicoterapias"],"correta":"C"},{"numero":59,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Para a Organização Mundial da Saúde, a saúde mental pode ser considerada um estado de bem -estar vivido pelo indivíduo, que possibilita o desenvolvimento de suas habilidades pessoais para responder aos desafios da vida e contribuir com a comunidade. Analisando o conceito de saúde mental da OMS a partir de uma perspectiva crítica, um dos fatores fundamentais para o trabalho da psicologia nos contextos de saúde é","alternativas":["compreender a saúde mental a partir de aspectos de personalidade e temperamento.","associar a saúde mental com a manutenção de equilíbrio emocional e resiliência individuais.","identificar a saúde mental como ausência de sofrimento psíquico e de diagnósticos psiquiátricos.","correlacionar saúde mental e produtividade, expressa pela capacidade de se inserir e se manter em atividade laboral.","considerar que a saúde mental não se reduz a um atributo individual, mas sim inserida nas condições socioculturais de um contexto"],"correta":"E"}]},{"codigo":"fhemig-enfermeiro-40h","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/profissional-de-enfermagem-penf-enfermeiro-40h-nivel-ivcns302-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitivo-fhemig-retificado-01.11.2023.pdf","cargo":"Enfermeiro 40h","orgao":"FHEMIG","ano":2023,"questoes":[{"numero":31,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Considerando as diretrizes do Ministério da Saúde e da Sociedade Brasileira de Cardiologia, assinale a opção que indica um fator de risco para doença cardiovascular.","alternativas":["HDL-c < 60mg/DL","Pressão de pulso em idosos < 65 mmHg.","Triglicerídeos (TG) > 100mg/dL em jejum.","Circunferência abdominal > 95 cm para homens.","Circunferência abdominal > 88 cm para mulheres"],"correta":"E"},{"numero":32,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Para tratamento da Covid -19 no Sistema Único de Saúde (SUS), em março de 2022, o Ministério da Saúde aprovou a incorporação do Baricitinibe 4mg. Acerca da administração desse medicamento, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O medicamento deve ser utilizado, exclusivamente, por pacientes com Covid -19 hospitalizados que necessitam de oxigênio por máscara ou cateter nasal, ou de alto fluxo de oxigênio ou ventilação não invasiva. ( ) O Baricitinibe 4 mg é contraindicado para mulheres grávidas e idosos acima de 65 anos. ( ) O Bari citinibe pode ser administrado por via oral, tubo de alimentação por gastrostomia e sonda de alimentação nasogástrica ou orogástrica. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – F – V.","F – V – F.","V – V – V.","F – F – V.","V – F – F"],"correta":"A"},{"numero":33,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Com base nos aspectos clínicos e epidemiológicos da Febre Maculosa (FMB), assinale a afirmativa correta.","alternativas":["A febre maculosa produzida pela Rickettsia parkeri apresenta quadros febris agudos e manifestações graves, frequentemente letais.","O exantema é o sinal clínico mais importante e está presente em todos os quadros de febre maculosa.","O período de incubação da FMB é, em média, de 10 dias, podendo variar de 7 a 21 dias.","A terapêutica empregada rotineiramente por um período de 14 dias deve ser mantida por 7 dias após o término da febre.","Em geral, entre o segundo e o sexto dia da doença, surge o exantema maculopapular, de evolução centrípeta e predomínio nos membros inferiores"],"correta":"E"},{"numero":34,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Acerca dos cuidados a pacientes vítimas de queimaduras, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Na queimadura térmica, a meta de reanimação volêmica para pacientes adultos é manter o débito urinário em 1,0mL/kg/h e, no trauma elétrico, de 2mL/kg/h. ( ) Em pacientes idosos ou em crianças, considera -se um grande queimado aquele com Superfície Corporal Queimada - SCQ >10% e >20%, respectivamente. ( ) Segundo as recomendações do Ministério da Saúde, deve -se administrar 1 reforço da vacina antitetânica para os pacientes que receberam o último reforço há mais de 5 e a menos de 10 anos, e que apresentem queimaduras de 2º ou 3º grau. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – V – V.","F – F – F.","F – F – V.","V – V – F.","V – F – V"],"correta":"C"},{"numero":35,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Um paciente adulto, em tratamento de câncer de pulmão, apresentou as seguintes características: capacidade de marcha bastante prejudicada, permanecendo o dia todo sentado; mobilidade ligeiramente limitada, mas consegue fazer algumas alterações na posição d o corpo; percepção sensorial levemente limitada; pele ocasionalmente úmida, requerendo troca extra da roupa de cama por dia; nutrição muito pobre, nunca come uma refeição completa; e potencial problemas com fricção e cisalhamento. De acordo com a escala de Bradem, o risco de lesão por pressão desse paciente é","alternativas":["leve.","baixo.","alto.","moderado.","muito alto"],"correta":"D"},{"numero":36,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"Em um recém-nascido com sinais de asfixia, a massagem cardíaca é indicada se, após 30 segundos de ventilação com pressão positiva (VPP) e técnica adequada, a frequência cardíaca estiver abaixo de","alternativas":["60bpm.","70bpm.","80bpm.","90bpm.","100bpm."],"correta":"A"},{"numero":37,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"Considerando o protocolo de cirurgia segura do Ministério da Saúde, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A identificação do sítio cirúrgico deve ser realizada por médico membro da equipe cirúrgica antes do encaminhamento do paciente para o local de realização da cirurgia. ( ) Antes de o paciente sair da sala de cirurgia, deve ser verificado se as contagens de instrumentais cirúrgicos, compressas e agulhas estão corretas. ( ) Deve ser confirmado com o anestesista, antes da indução anestésica, se o paciente tem risco de perder mais de 500mL de sangue (mais de 7mL/kg em crianças) durante a cirurgia, a fim de garantir a preparação para essa eventualidade. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – V – F.","F – F – F.","V – F – V.","F – V – F.","V – V – V"],"correta":"E"},{"numero":38,"disciplina":"Enfermagem","assunto":"Processo de Enfermagem e SAE","enunciado":"O enfermeiro faz a ausculta cardíaca e pulmonar em uma paciente com insuficiência cardíaca. Com relação às etapas da sistematização da assistência de enfermagem, o procedimento realizado corresponde à(ao)","alternativas":["avaliação.","histórico.","diagnóstico.","implementação.","planejamento"],"correta":"B"},{"numero":41,"disciplina":"Enfermagem","assunto":"Diabetes Mellitus","enunciado":"Durante a avaliação de um paciente adulto com Diabetes mellitus não controlada, o Enfermeiro identificou pé diabético neuropático. Assinale a opção que indica características dessa condição.","alternativas":["Pulso pedial diminuído e pele fria.","Ausência de edema e deformidades.","Palidez com elevação e sensação dolorosa.","Dedo em garra e sensibilidade diminuída.","Cianose com declive e pele fina e brilhante"],"correta":"D"},{"numero":42,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Durante o exame físico de um paciente adulto, sexo masculino, o Enfermeiro identificou sinais característicos da Tríade de Beck. Assinale a opção que os apresenta.","alternativas":["Bradicardia, hipertensão arterial e bradipneia.","Febre com calafrios, dor abdominal e icterícia.","Estase de jugular, hipofonose de bulhas e hipotensão.","Hipercoagulabilidade, estase venosa e lesão endotelial.","Coagulopatia, hipotermia e acidose metabólica"],"correta":"C"},{"numero":43,"disciplina":"Enfermagem","assunto":"Processo de Enfermagem e SAE","enunciado":"Assinale a opção que apresenta os eixos da CIPE que foram utilizados na construção do diagnóstico ventilação espontânea prejudicada.","alternativas":["Ação e tempo.","Foco e julgamento.","Ação e localização.","Julgamento e ação.","Foco e localização."],"correta":"B"},{"numero":44,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Paciente do sexo masculino, 59 anos, procurou a unidade de emergência, com queixa de diarreia e vômito há três dias. Refere piora nas últimas 24 horas, com cerca de 3 evacuações de aspecto líquido, presença de febre e 2 episódios de vômito, além de fraqueza e palpitações. O exame de gasometria arterial indicou níveis de pH = 7,30; [HCO3 –] = 16mEq/L; PaCO2 = 30mmHg; e BE = –1,0. Com base nos sintomas apresentados e nos valores da gasometria, esse paciente apresenta","alternativas":["alcalose metabólica.","acidose respiratória.","acidose metabólica.","alcalose respiratória.","acidose respiratória compensada"],"correta":"C"}]},{"codigo":"ebserh-fisio-gp7","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/grupo-7-fisioterapiae3cnsgp07-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/ebserrhassistencial2024_gabarito_definitivo.pdf","cargo":"Fisioterapia — saúde","orgao":"EBSERH","ano":2025,"questoes":[{"numero":33,"disciplina":"Enfermagem","assunto":"Saúde do Idoso","enunciado":"Para avaliar a mobilidade e o equilíbrio funcional, o fisioterapeuta mede o tempo em segundos que o indivíduo leva para se levantar de uma cadeira, percorrer uma distância de três metros, girar, retornar para a cadeira e sentar-se novamente. O cronômetro é disparado após o sinal de partida e parado somente quando o indivíduo se coloca novamente na posição inicial, sentado com as costas apoiadas na cadeira. O procedimento descrito é a aplicação do seguinte teste:","alternativas":["Test Timed Up and Go (TUG).","Dynamic Gait Index (DGI).","Medida de Independência Funcional (MIF).","Escala de Avaliação de Fugl-Meyer (EFM).","Velocidade da marcha dos 10 metros"],"correta":"A"},{"numero":45,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Em fisioterapia respiratória, são obser vados o padrão e o ritmo respiratórios que podem indicar alterações patológicas. O ritmo respiratório que apresenta uma fase de apneia seguida de uma série de inspirações profundas até o máximo, seguida de decréscimo até nova pausa, caracteriza uma anormal idade do ritmo e da frequência do ritmo respiratório, conhecida como","alternativas":["respiração atáxica.","respiração de Biot.","hiperpneia.","taquipneia.","respiração de Cheyne Stokes"],"correta":"E"},{"numero":46,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Em semiologia respiratória, para se observar uma correlação clínica, é importante anotar o sexo biológico do paciente, pois algumas patologias são mais comuns em um sexo do que em outro. Uma patologia muito comum em mulheres é","alternativas":["a anemia falciforme.","o adenocarcinoma brônquico.","a tuberculose.","o enfisema.","a bronquite crônica"],"correta":"B"},{"numero":47,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"Para o paciente hospitalizado, o exame da pele é indispensável, devido às correlações clínicas. Um dos aspectos a ser observado é a coloração, localizada e generalizada. Avalie se a palidez generalizada indica: I. obstrução da artéria femoral; II. diminuição das hemácias circulantes; III. vasoconstrição por estímulos neurogênicos; IV. vasoconstrição por estímulos hormonais. Estão corretos os itens","alternativas":["I, II, III e IV.","I, III e IV, apenas.","II, III e IV, apenas.","II e IV, apenas.","I, II e III, apenas."],"correta":"C"},{"numero":49,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Aspiração endotraqueal é um procedimento que objetiva a remoção de secreções em vias aéreas superiores e inferiores, utilizado em pacientes em ventilação mecânica ou em respiração espontânea. Por ser um procedimento com riscos potenciais, requer técnica ap urada, monitoramento constante e cuidados especiais. Em relação a esse procedimento, avalie as afirmativas a seguir. I. Para calcular o tamanho da sonda usa -se a fórmula: tamanho da cânula× 3 2 . II. Antes, durante e após a aspiração deve -se monitorar o paciente observando -se, entre outros fatores, a frequência cardíaca. III. Antes, durante e após a aspiração deve -se observar a pressão intracraniana em paciente monitorado. IV. Aumento da pressão inspiratória em pacientes ventilados em modalidade à pressão, é um sinal que evidencia a necessidade de aspiração. Estão corretas apenas as afirmativas","alternativas":["I, II e III.","I, II e IV.","II, III e IV.","II e III.","I e II"],"correta":"A"},{"numero":50,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"Os recém-nascidos a termo e pré -termo sentem mais dor que as crianças maiores e os adultos, pois não têm as vias inibitórias bem desenvolvidas. Uma escala importante para medir a dor é a Escala de NIPS (Neonatal Infant Pain Scale). Acerca da Escala NIPS, é correto afirmar que","alternativas":["tem 4 indicadores de dor, avaliados de 0 a 1 ponto.","tem 6 indicadores de dor, avaliados de 0 a 2 pontos.","pontuação igual ou maior do que 6 indica presença de dor.","é utilizada apenas em recém-nascidos a termo.","é utilizada apenas em recém-nascidos a pré-termo"],"correta":"B"},{"numero":52,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"A aterosclerose resulta em um estreitamento da luz arterial, mas a trombose é a maior responsável pelos efeitos cardiovasculares. Em relação ao coração, os eventos que resultam da formação de trombos no interior das artérias coronárias são","alternativas":["angina instável e ataque cardíaco.","angina instável e arritmia sinusal.","insuficiência ventricular esquerda ou direita.","hipertrofia miocárdica e hipertensão.","apoplexia e hipertensão"],"correta":"A"},{"numero":58,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Durante a gestação, o exercício é indicado observando -se alguns cuidados. Há, entretanto, exercícios / atividades que são contraindicados. Uma contraindicação para a gestante é","alternativas":["o treino de força.","o mergulho em profundidade com descompressão.","a caminhada acelerada.","o ciclismo.","a natação."],"correta":"B"},{"numero":59,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"O climatério ocorre na meia -idade da mulher, período em que ocorrem alterações importantes, entre elas, a incontinência urinária. Em relação à incontinê ncia urinária da mulher, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O hipoestrogenismo altera a função de estruturas do assoalho pélvico. ( ) A perda de urina acontece pelo desequilíbrio entre as pressões uretral e vesical. ( ) A incontinência só ocorre em momentos de esforço extremo. ( ) A musculatura do assoalho pélvico sofre retração tecidual e aumento tônico. As afirmativas são, respectivamente,","alternativas":["V – V – V – V.","F – F – V – V.","V – V – F – F.","V – F – F – V.","V – V – F – V"],"correta":"C"}]},{"codigo":"ebserh-nutricao-gp9","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/grupo-9-nutricionistae3cnsgp09-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/ebserrhassistencial2024_gabarito_definitivo.pdf","cargo":"Nutrição — saúde","orgao":"EBSERH","ano":2025,"questoes":[{"numero":33,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Sabe-se que a gestação é um momento biológico especial na vida de uma mulher, sobretudo quanto às mudanças fisiológicas e necessidades nutricionais inerentes a esse período. Nesse contexto, avalie as afirmativas a seguir e assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) O volume sanguíneo aumenta até o fim da gestação, resultando em concentrações aumentadas de hemoglobina, albumina no soro, outras proteínas séricas e vitaminas hidrossolúveis, principalmente após o fim d o primeiro trimestre. ( ) O aumento da concentração de progesterona intensifica a motilidade gastrintestinal e a reabsorção de água, favorecendo a constipação intestinal; logo, uma maior ingestão de fibras insolúveis (como cascas de frutas e legumes), assim como de líquidos é recomendada. ( ) Na gestação, o fluxo plasmático renal aumenta devido à diminuição da taxa de filtração glomerular com maiores concentrações de creatinina sérica e nitrogênio ureico sanguíneo; logo, é recomendada uma dieta hiperp roteica desde o período pós-concepção. As afirmativas são, respectivamente,","alternativas":["V – V – F.","V – F – V.","F – V – F.","F – F – V.","F – F – F"],"correta":"E"},{"numero":34,"disciplina":"Saúde Coletiva I","assunto":"Promoção da Saúde","enunciado":"A Educação Alimentar e Nutricional (EAN) insere -se em uma das diretrizes da Política Nacional de Segurança Alimentar e Nutricional (PNSAN) e, assim, se configura como estratégia fundamental para o enfrentamento das problemáticas brasileiras referentes à má nutrição. Diante disso, quanto à EAN, avalie as afirmativas a seguir. I. O Marco de Referência de EAN para as Políticas Públicas, o Guia Alimentar para a População Brasileira e a Estratégia Intersetorial de Prevenção e Controle da Obesidade são considerados documentos normativos e orientadores acerca das políticas e ações de Educação Alimentar e Nutricional. II. Conforme o Decreto nº 7.272, de 25 de agosto de 2010, a EAN é uma diretriz da Política Nacional de Vigilância Sanitária que, desde então, vem sendo trabalhada em uma perspectiva mais ampliada em diferentes campos de ação, no escopo do sistema alimentar, e articulada a outras políticas públicas. III. A abordagem parcial do sistema alimentar e a ação educativa passiva, dialógica e não problematizado ra articulam-se com o princípio da EAN denominado “sustentabilidade social, ambiental e econômica”. Está correto o que se afirma em","alternativas":["I, apenas.","III, apenas.","I e II, apenas.","I e III, apenas.","I, II e III."],"correta":"A"},{"numero":36,"disciplina":"Enfermagem","assunto":"Saúde do Idoso","enunciado":"O envelhecimento da população traz consigo a necessidade de ações efetivas dos setores de saúde, assim como a criação de políticas públicas que visem maior qualidade de vida e um envelhecer ativo, tendo na alimentação saudável um pilar para esse desfecho. Assim, quanto às recomendações voltadas ao público idoso, assinala a afirmativa correta.","alternativas":["Recomenda-se o consumo de refeições volumosas durante o dia, favorecendo maior aceitação pelo idoso, assim como uma digestão completa.","Recomenda-se a ingestão de arroz com feijão diariamente, pois essa combinação garante o aporte de vitamina B12, proteínas de baixo valor biológico e ferro no seu estado férrico.","Recomenda-se o consumo preferencial de carnes brancas, como pescados e aves sem pele, assim como cortes bovinos mais magros.","Recomenda-se a utilização de gordura animal para o preparo dos alimentos, uma vez que são fontes de ácidos graxos poli - insaturados.","Recomenda-se o consumo moderado de sal refinado, restringindo a ingestão máxima de 5g do mesmo em cada refeição do dia"],"correta":"C"},{"numero":44,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Com base nas orien tações do SISVAN quanto às técnicas de medição e equipamentos utilizados na Antropometria, avalie as afirmativas a seguir: I. Recomenda-se que o antropômetro horizontal (para medir o comprimento de crianças menores de dois anos) e a balança pediátrica seja m apoiados em mesa ou bancada, confeccionadas em material firme e resistente (por exemplo, metal, mármore ou madeira). II. É recomendável que as balanças pediátricas tenham precisão mínima de dez gramas e, as balanças tipo plataforma, de cem gramas, porque pequenas alterações no peso são indicadores nutricionais importantes, em particular para as crianças menores de dois anos. III. A balança mecânica de plataforma deve estar afastada da parede ao ser usada; deve-se destravar a balança e verificar se ela está calibrada (a agulha do braço e o fiel devem estar na mesma linha horizontal); após a calibração, a balança deve ser travada e só então o indivíduo subirá na plataforma para ser pesado. Está correto o que se afirma em","alternativas":["I, apenas.","III, apenas.","I e II, apenas.","I e III, apenas.","I, II e III"],"correta":"E"},{"numero":48,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"A Diretriz BRASPEN de Terapia Nutricio nal no Paciente Grave, publicada em 2023, formula linhas de tratamento baseadas no contexto multidisciplinar, promovendo a uniformização das práticas de terapia nutricional. Quanto ao documento supracitado referente ao suporte nutricional enteral e parenteral, é correto afirmar que","alternativas":["no paciente grave, recomenda-se iniciar a nutrição parenteral suplementar (NPS) na primeira semana de hospitalização, isto é, precocemente.","para pacientes graves, o uso de nutrição parenteral pronta apresenta superior idade clínica quando comparada à individualizada.","na vigência da insuficiência renal aguda, os pacientes críticos devem receber fórmulas enterais diferenciadas e com recomendações energéticas aumentadas.","o uso de glutamina para pacientes queimado s é fortemente recomendado, sugerindo -se doses elevadas diárias para recuperação do estado nutricional.","sugere-se a nutrição enteral em posição gástrica como padrão; considerar posicionamento pós -pilórico em casos específicos como, por exemplo, quando há alto risco para aspiração"],"correta":"E"},{"numero":52,"disciplina":"Saúde Coletiva I","assunto":"Promoção da Saúde","enunciado":"A alimentação e a nutrição configuram os pilares fundamentai s para a promoção e a proteção da saúde, possibilitando crescimento e desenvolvimento adequados, assim como qualidade de vida e cidadania. Entretanto, quando tais requisitos não são atendidos, surgem inúmeros distúrbios nutricionais caracterizados, então, como problemas de saúde pública. Neste contexto, avalie as afirmativas a seguir: I. A obesidade em crianças e adolescentes é um problema grave, que ocasiona repercussões deletérias na vida adulta, sobrecarregando os cofres públicos com altos custos relacionados ao tratamento do agravo e de suas complicações. II. Sabe-se que o bócio é causado pela ingestão deficiente de fósforo, sendo um grave problema de saúde pública, inclusive pelo risco de associação com o cretinismo e a surdo -mudez irreversíveis. III. As pesquisas apontam a persistência das deficiências de ferro e vitamina A, assim como o ressurgimento de casos de Beribéri (deficiência de tiamina ou vitamina B1) em alguns estados brasileiros. Está correto o que se afirma em","alternativas":["I, apenas.","III, apenas.","I e II, apenas.","I e III, apenas.","I, II e III"],"correta":"D"},{"numero":57,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Paciente Paulo Silva, 69 anos, com enfisema pulmonar, deu entrada na emergência com grave desconforto respiratório e desorientação. Após avaliação clínica e laboratorial, Paulo foi diagnosticado com acidose respiratória. Considerando tal caso clínico, os aspectos fisiopatológicos e o manejo nutricional, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A acidose respiratória é causada pela diminuição da ventilação pulmonar, resultando em acúmulo sanguíneo de dióxido de carbono (CO2); tal quadro, geralmente, favorece a diminuição do pH do sangue, assim como aumento da pressão parcial de CO2 (PCO2), visualizados pelo exame de gasometria arterial. ( ) Quando há um desequilíbrio ácido -base, são acionados mecanismos de compensação, isto é, sistema tampão, atuação respiratória e/ou renal; no caso clínico apr esentado, na tentativa de retornar à homeostase, possivelmente, houve aumento da excreção ácida líquida renal, concomitantemente à diminuição do bicarbonato sérico. ( ) O manejo nutricional visando à regulação do equilíbrio eletrolítico e hídrico pode incluir a mudança de sais de cloreto e acetato na nutrição com via parenteral, manipulação de macronutrientes para evitar a superalimentação, assim como ajuste na oferta de líquidos e eletrólitos. As afirmativas são, respectivamente.","alternativas":["V – V – F.","V – F – V.","F – V – F.","F – F – V.","F – F – F"],"correta":"B"},{"numero":59,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"As doenças renais agudas e crônicas são altamente prevalentes e representam causas importantes de morbimortalidade. Em relação à doença renal crônica (DRC), à luz da Diretriz BRASPEN de Terapia Nutricional no paciente com doença renal, publicada em 2021, é correto afirmar que","alternativas":["a recomendação de energia é de 10 -15 kcal/kg/dia para pacientes metabolicamente estáveis, baseado em idade, sexo, atividade física, estado nutricional , estágio da DRC e comorbidades associadas.","a dieta com, aproximadamente, 0,3 -0,4 g/kg/dia de proteína suplementada com cetoanálogos, ou aminoácidos essenciais, para pacientes com DRC G4-5 diminui o risco de falência renal, e reduz a proteinúria.","para pacientes adultos com DRC G3 -5D, maior ingestão de fósforo deve ser indicada na presença de hiperfosfatemia persistente; além disso, a ingestão alimentar de sódio recomendada é de menos de 7,0 g/dia.","os aportes de energia e proteínas para crianças com DRC G2-5 são semelhantes àquelas saudáveis, para a idade cronológica, mas no seu limite inferior; para adolescentes, é recomendada restrição proteica, independentemente do grau de DRC.","a recomendação de energia e nutrientes depende do período do transplante renal (TR); no TR imediato e em caso de rejeição aguda do enxerto, a recomendação de proteínas é de 2,1 a 4,5 g/kg de peso atual ou ideal."],"correta":"B"}]},{"codigo":"ebserh-farmacia-gp5","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/grupo-5-farmaciae3cnsgp05-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/ebserrhassistencial2024_gabarito_definitivo.pdf","cargo":"Farmácia — saúde","orgao":"EBSERH","ano":2025,"questoes":[{"numero":32,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Na construção de um Mapa de Risco, são empregadas cores para designar o grupo ao qual pertence um dado risco. Assinale a opção que indica um grupo incorreto.","alternativas":["Grupo 2: riscos químicos identificados pela cor vermelha.","Grupo 5: riscos de acidentes identificados pela cor azul.","Grupo 1: riscos físico-químicos identificados pela cor laranja.","Grupo 4: riscos ergonômicos identificados pela cor amarela.","Grupo 3: riscos biológicos identificados pela cor marrom"],"correta":"C"},{"numero":35,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"A potencial consequência ou interferência em resultados de exames laboratoriais decorrentes da hemólise, um processo que pode ocorrer se a coleta de sangue não for realizada adequadamente, levando à destruição de glóbulos vermelhos, é","alternativas":["a diminuição da concentração de constituintes que existem em maior quantidade nos eritrócitos do que no plasma (ou soro).","o aumento da concentração das substâncias que são mais abundantes nas hemácias do que no plasma (ou soro).","a manutenção da cor original d o plasma (ou soro), apesar do escape da hemoglobina das hemácias.","o aumento da concentração de constituintes que existem em menor quantidade nos eritrócitos do que no plasma (ou soro).","a diminuição da concentração das substâncias que são mais abundantes nas hemácias do que no plasma (ou soro)"],"correta":"B"},{"numero":36,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"A exposição ocupacional a materiais biológicos contaminados representa um risco significativo para profissionais da saúde, especialmente no que se refere às infecções associadas à hepatite B (HBV) e à hepatite C (HCV). Sobre a prevenção, o controle e as consequências dessas infecções no ambiente hospitalar e laboratorial, assinale a afirmativa correta.","alternativas":["A infecção pela HBV em profissionais da saúde ocorre exclusivamente por contato direto com o sangue contaminado, sendo improvável a transmissão por outras secreções biológicas.","Não há vacina disponível para a hepatite B, sendo a profilaxia pós-exposição a única medida eficaz de controle da doença em profissionais da saúde.","O risco de infecção ocupacional pela hepatite C é maior do que pela HBV, pois a HCV apresenta maior taxa de transmissão e alta virulência em exposições acidentais.","A vacinação contra a hepatite B é uma medida eficaz e recomendada para todos os profissiona is da saúde, devendo ser associada ao monitoramento sorológico para confirmar a imunização.","A profilaxia pós -exposição à hepatite C consiste na administração de imunoglobulina específica, a qual deve ser aplicada nas primeiras 24 horas após o acidente ocupacional"],"correta":"D"},{"numero":40,"disciplina":"Enfermagem","assunto":"Diabetes Mellitus","enunciado":"A dosagem de HbA1C (hemoglobina glicada) é um exame que mede o controle glicêmico ao longo dos últimos 2 a 3 meses, fornecendo uma média dos níveis de glicose no sangue durante esse período. Ela é utilizada principalmente para o diagnóstico e monitoramento do diabetes. Dos fatores a seguir, assinale o que promove resultados falsamente aumentados de HbA1C.","alternativas":["Hipertiroidismo.","Presença de concentrações elevadas de vitamina C e vitamina E.","Hemoglobinopatias (HbS, HbC).","Presença de hemoglobina carbamilada em pacientes com insuficiência renal.","Mieloma múltiplo"],"correta":"D"},{"numero":42,"disciplina":"Enfermagem","assunto":"Centro de Material e Esterilização (CME)","enunciado":"A desinfecção e a esterilização química são processos essenciais na eliminação de microrganismos em objetos e superfícies inanimadas. Para garantir a eficácia desses procedimentos, é fundamental selecionar corretamente os agentes quími cos conforme suas características e seu espectro de ação. Sobre os principais desinfetantes e esterilizantes químicos utilizados em laboratórios e ambientes de assistência à saúde, as afirmativas a seguir estão corretas, à exceção de uma. Assinale-a.","alternativas":["O glutaraldeído é amplamente utilizado para desinfecção de alto nível de artigos semicríticos, possuindo atividade esporocida quando em tempo de exposição adequado.","O ácido peracético apresenta ampla atividade antimicrobiana, sendo eficaz contra es poros bacterianos, micobactérias e fungos, além de possuir baixa toxicidade ambiental.","Os compostos fenólicos são recomendados para a desinfecção de artigos semicríticos e superfícies em áreas críticas, incluindo UTI e centro cirúrgico, podendo ser uti lizados para a desinfecção de materiais de látex e acrílico sem restrições.","Os iodóforos são efetivos na eliminação de microrganismos em tecidos vivos e superfícies inanimadas, sendo frequentemente utilizados para a desinfecção de equipamentos médicos e como antissépticos na prática clínica.","Os álcoois etílico e isopropílico têm atividade contra bactérias vegetativas, alguns vírus e fungos, sendo ineficazes contra esporos bacterianos e vírus hidrofílicos."],"correta":"C"},{"numero":49,"disciplina":"Enfermagem","assunto":"Gerenciamento de Resíduos de Serviços de Saúde (GRSS)","enunciado":"A incompatibilidade química entre as principais substâncias utilizadas pelos geradores de Resíduos de Serviços de Saúde é informada no Anexo IV da RDC Anvisa nº 222 de 28 de março de 2018, que regulamenta as boas práticas de gerenciamento dos Resíduos de Serviços de Saúde (RSS) e dá outras providências. Devido a determinadas propriedades químicas, algumas substâncias podem reagir violentamente entre si, resultando em explosão ou produzindo gases altamente tóxicos ou inflamáveis. Para o ácido oxálico, segundo essa RDC, as substâncias incompatíveis incluem:","alternativas":["sais de amônio, ácidos, metais em pó, matérias o rgânicas particuladas e substâncias combustíveis.","ácido nítrico, nitrato de amônio, óxido de cromo VI, peróxidos, flúor, cloro, bromo e hidrogênio.","benzeno, hidróxido de amônio, benzina de petróleo, hidrogênio, acetileno, etano, propano, butadienos e pós - metálicos.","prata e mercúrio.","ácido acético, naftaleno, cânfora, glicerol, turpentine e álcool, e outros líquidos inflamáveis"],"correta":"D"},{"numero":51,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"A resistência aos antibióticos é um grave problema de saúde global que resulta do uso indiscriminado e inadequado dessas substâncias. As bactérias frequentemente desenvolvem mecanismos de resistência que reduzem a eficácia da terapia antim icrobiana, tornando as infecções mais difíceis de controlar. Isso leva ao aumento da morbidade, mortalidade e custos com a saúde. Dos diversos mecanismos de resistência bacteriana, é correto afirmar que a resistência à vancomicina ocorre principalmente em","alternativas":["Enterobacter resistentes à vancomicina (ERV) e envolve a modificação do alvo da vancomicina, a glucana da parede celular. Essa resistência é mediada por genes como vanA ou vanB, que promovem a substituição do terminal D -alanina-D- alanina (alvo da vanco micina) por D -alanina-D-lactato ou D - alanina-D-serina, reduzindo a afinidade da vancomicina pela glucana. Isso impede a inibição da síntese da parede celular bacteriana, permitindo que a bactéria sobreviva e se prolifere mesmo na presença do antibiótico.","Enterococcus resistentes à vancomicina (ERV) e envolve a modificação do alvo da vancomicina, a glucana da parede celular. Essa resistência é mediada por genes como vanA ou vanB, que promovem a substituição do terminal D -alanina-D- alanina (alvo da vancom icina) por D -alanina-D-lactato ou D - alanina-D-serina, reduzindo a afinidade da vancomicina pela glucana. Isso impede a inibição da síntese da parede celular bacteriana, permitindo que a bactéria sobreviva e se prolifere mesmo na presença do antibiótico.","Enterobacter resistentes à vancomicina (ERV) e envolve a modificação do alvo da vancomicina, o peptidoglicano da parede celular. Essa resistência é mediada por genes como vanA ou vanB, que promovem a substituição do terminal D - alanina-D-alanina (alvo da vancomicina) por D -alanina-D- lactato ou D -alanina-D-serina, reduzindo a afinidade da vancomicina pelo peptidoglicano. Isso impede a inibição da síntese da parede celular bacteriana, permitindo que a bactéria sobreviva e se prolifere mesmo na presença do antibiótico.","Enterococcus resistentes à vancomicina (ERV) e envolve a modificação do alvo da vancomicina, o peptidoglicano da parede celular. Essa resistência é mediada por genes como vanA ou vanB, que promovem a substituição do terminal D - alanina-D-alanina (alvo da vancomicina) por D -alanina-D- lactato ou D -alanina-D-serina, reduzindo a afinidade da vancomicina pelo peptidoglicano. Isso impede a inibição da síntese da parede celular bacteriana, permitindo que a bactéria sobreviva e se prolifere mesmo na p resença do antibiótico.","Enterococcus resistentes à vancomicina (ERV) e envolve a modificação do alvo da vancomicina, os lipopolissacarídeos da parede celular. Essa resistência é mediada por genes como vanA ou vanB, que promovem a substituição do termin al D- alanina-D-alanina (alvo da vancomicina) por D -alanina-D- lactato ou D -alanina-D-serina, reduzindo a afinidade da vancomicina pelos lipopolissacarídeos. Isso impede a inibição da síntese da parede celular bacteriana, permitindo que a bactéria sobreviva e se prolifere mesmo na presença do antibiótico"],"correta":"D"},{"numero":55,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"Com base no modo como a estrutura física de uma farmácia hospitalar deve ser organizada para otimizar os fluxos de trabalho, incluindo o recebimento, o armazenamento de medicamentos, a dispensação e o acompanhamento do paciente, avalie as afirmativas a seguir e identifique a única incorreta.","alternativas":["A farmácia hospitalar deve contar com áreas distintas para o armazenamento, a manipulação, a dispensação e as atividades administrativas, de acordo com as boas práticas de farmácia.","A sala destinada à manipulação de medicamentos antineoplásicos deve possuir pressão negativa em relação às áreas adjacentes e uma cabine de segurança biológica classe II B2, conforme regulamentações da Anvisa.","A área de armazenamento de medicamentos termolábeis deve ser equipada com dispositivos que permitam monitoramento contínuo de temperatura e umidade, garantindo a integridade dos produtos.","O planejamento estrutural da farmácia hospitalar deve incluir fluxos físicos e operacionais bem definidos para minimizar riscos de contaminação cruzada e garantir a segurança dos medicamentos.","A estrutura física da farmácia hospitalar deve ser planejada para atender às demand as específicas da instituição, sendo facultativa a inclusão de áreas exclusivas para manipulação de medicamentos em hospitais de pequeno porte, desde que os medicamentos sejam adquiridos prontos para uso"],"correta":"E"},{"numero":56,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"No contexto laboratorial, a cla ssificação ABO é fundamental para a segurança transfusional. Contudo, discrepâncias podem ocorrer entre a prova direta (globular) e a prova reversa (sérica), comprometendo a correta determinação do grupo sanguíneo. Com base nas causas de discrepâncias na classificação ABO, assinale a afirmativa correta.","alternativas":["Subgrupos de A ou AB sempre causam discrepâncias na prova direta, devido à presença de anticorpos naturais anti-A1.","Em recém-nascidos, a ausência de anticorpos naturais anti -A ou anti-B impossibilita a realização da prova reversa, devendo- se basear apenas na prova direta para a classificação ABO.","O fenômeno de Rouleaux, caracterizado pelo empilhamento de hemácias, pode gerar resultados falso -positivos em ambas as provas, sendo corrigido por lavagem das hemácias.","A gelatina de Wharton presente em amostras de sangue do cordão umbilical pode causar aglutinação inespecífica, levando a resultados falso-negativos na prova direta.","Pacientes imunodeprimidos apresentam frequentemente poliaglutinação das hemácias, o que impede a realização de ambas as provas para classificação ABO"],"correta":"B"},{"numero":59,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"No contexto da vigilância do receptor de transfusão, assinale a conduta correta diante de uma reação transfusional com suspeita de reação hemolítica imunológica tardia, conforme as diretrizes da Anvisa (Manual p ara o Sistema Nacional de Hemovigilância no Brasil, 2022).","alternativas":["A suspeita deve ser comunicada à vigilância sanitária local apenas se houver comprovação laboratorial de hemólise em um período superior a 24 horas após a transfusão.","A investigação deve incluir testes de compatibilidade cruzada retrospectiva utilizando apenas as bolsas transfundidas nas últimas 72 horas.","A coleta de novas amostras de sangue do receptor é obrigatória e deve incluir testes para anticorpos irregulares, pesquisa de antígenos eritrocitários e hemoglobina livre.","A notificação da suspeita ao sistema de hemovigilância é dispensada caso o paciente tenha histórico de anticorpos eritrocitários detectados antes da transfusão.","O acompanhamento clínico do paciente pode ser encerrado se os sinais clínicos iniciais de hemólise desaparecerem espontaneamente em até 48 horas após o evento transfusional"],"correta":"C"},{"numero":60,"disciplina":"Enfermagem","assunto":"Gerenciamento de Resíduos de Serviços de Saúde (GRSS)","enunciado":"A RDC Anvisa nº 222 de 28 de março de 2018 detalha os requisitos técnicos para o manejo, o acondicionamento e a destinação de Resíduos de Serviços de Saúde (RSS). Sobre os procedimentos para resíduos do grupo A com múltiplos riscos associados, assinale a afirmativa correta.","alternativas":["Resíduos do grupo A contaminados com agentes biológicos de classe de risco 4 devem ser tratados exclusivamente na unidade geradora, utilizando tecnologias compatíveis com o Nível III de inativação microbiana.","Para resíduos do grupo A contaminados com agentes biológicos de classe de risco 3 e 4, o tratament o pode ser realizado fora da unidade geradora, desde que respeitadas as normas estaduais de transporte de resíduos perigosos.","Quando resíduos do grupo A apresentam risco biológico associado a risco químico, a escolha do método de tratamento deve priori zar a eliminação do risco químico, podendo o tratamento biológico ser dispensado se não houver risco de disseminação.","Os resíduos do grupo A com riscos biológicos e químicos devem ser submetidos prioritariamente à incineração, independentemente de outr as opções tecnológicas disponíveis no serviço gerador.","Quando resíduos do grupo A apresentam risco biológico e radiológico, o tratamento inicial deve ser direcionado ao risco biológico, independentemente do nível de radiação apresentado pelo resíduo."],"correta":"A"}]}] as const;
export async function sincronizarFGVEbserhFhemigSaude2025(){
 const user=await prisma.usuario.findFirst({orderBy:{id:"asc"},select:{id:true}});
 if(!user)return {inseridas:0,existentes:0,repetidas:0};
 const norm=(s:string)=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
 const banco=await prisma.questao.findMany({where:{fonte:FONTE_PROVAS_REAIS},select:{enunciado:true}});
 const hashes=new Set(banco.map(x=>norm(x.enunciado)));const disciplinas=new Map<string,number>();
 let inseridas=0,existentes=0,repetidas=0;
 for(const lote of LOTES)for(const q of lote.questoes){
 const origemId="fgv-"+lote.codigo+"-tipo1-q"+String(q.numero).padStart(2,"0");
 if(!q.enunciado.trim()||q.alternativas.length!==5||q.alternativas.some(x=>!x.trim())||
  !["A","B","C","D","E"].includes(q.correta)||new Set(q.alternativas.map(x=>x.trim().toLowerCase())).size!==5)
  throw new Error("[ebserh-fhemig-saude] Alternativas inválidas "+origemId);
 if(await prisma.questao.findFirst({where:{fonte:FONTE_PROVAS_REAIS,origemId},select:{id:true}})){existentes++;continue;}
 const h=norm(q.enunciado);if(hashes.has(h)){repetidas++;continue;}
 let disciplinaId=disciplinas.get(q.disciplina);
 if(!disciplinaId){
 let d=await prisma.disciplina.findFirst({where:{usuarioId:user.id,nome:{equals:q.disciplina,mode:"insensitive"}},select:{id:true}});
 if(!d)d=await prisma.disciplina.create({data:{usuarioId:user.id,nome:q.disciplina},select:{id:true}});
 disciplinaId=d.id;disciplinas.set(q.disciplina,disciplinaId);
 }
 await prisma.questao.create({data:{
 usuarioId:user.id,disciplinaId,tema:q.assunto,fonte:FONTE_PROVAS_REAIS,origemId,
 banca:"FGV",ano:lote.ano,orgao:lote.orgao,cargo:lote.cargo,fonteUrl:lote.prova,
 enunciado:q.enunciado,dificuldade:"medio",
 explicacao:"FGV/"+lote.orgao+" ("+lote.ano+"), "+lote.cargo+", Tipo 1, questão "+q.numero+
  ". Gabarito definitivo: alternativa "+q.correta+". Prova: "+lote.prova+" | Gabarito: "+lote.gabarito,
 alternativas:{create:q.alternativas.map((texto,i)=>({texto:"ABCDE"[i]+") "+texto,correta:"ABCDE"[i]===q.correta}))}
 }});
 hashes.add(h);inseridas++;
 }
 console.log("[ebserh-fhemig-saude-2025] "+inseridas+" inseridas; "+existentes+" existentes; "+repetidas+" repetidas ignoradas.");
 return {inseridas,existentes,repetidas};
}
